/**
 * Check if current time is within 24-hour edit window after session ends
 * @param {string} sessionDate - YYYY-MM-DD
 * @param {string} sessionEndTime - HH:MM
 * @returns {Object} { canEdit: boolean, hoursRemaining: number, message: string }
 */
function isWithinEditWindow(sessionDate, sessionEndTime) {
  const sessionEnd = new Date(`${sessionDate}T${sessionEndTime}:00`);
  const now = new Date();
  const hoursSinceEnd = (now - sessionEnd) / (1000 * 60 * 60);

  // Allow editing before session starts (for pre-marking)
  if (hoursSinceEnd < 0) {
    return { canEdit: true, hoursRemaining: 24, message: 'BuÃ¡Â»â€¢i hÃ¡Â»Âc chÃ†Â°a kÃ¡ÂºÂ¿t thÃƒÂºc' };
  }

  // Allow editing up to 24 hours after session ends
  if (hoursSinceEnd <= 24) {
    return {
      canEdit: true,
      hoursRemaining: Math.round((24 - hoursSinceEnd) * 10) / 10,
      message: `CÃƒÂ²n ${Math.round((24 - hoursSinceEnd) * 10) / 10} giÃ¡Â»Â Ã„â€˜Ã¡Â»Æ’ chÃ¡Â»â€°nh sÃ¡Â»Â­a`
    };
  }

  return {
    canEdit: false,
    hoursRemaining: 0,
    message: 'Ã„ÂÃƒÂ£ quÃƒÂ¡ 24 giÃ¡Â»Â, khÃƒÂ´ng thÃ¡Â»Æ’ chÃ¡Â»â€°nh sÃ¡Â»Â­a. LiÃƒÂªn hÃ¡Â»â€¡ Admin Ã„â€˜Ã¡Â»Æ’ override.'
  };
}

function formatDateOnlyLocal(date) {
  if (!(date instanceof Date) || Number.isNaN(date.getTime())) return null;
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

function parseDateOnlyLocal(dateStr) {
  if (!dateStr || typeof dateStr !== 'string') return null;
  const match = dateStr.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!match) return null;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  const parsed = new Date(year, month - 1, day);
  if (
    parsed.getFullYear() !== year ||
    parsed.getMonth() !== month - 1 ||
    parsed.getDate() !== day
  ) {
    return null;
  }
  parsed.setHours(0, 0, 0, 0);
  return parsed;
}

function getMonthDayFromDateOnly(dateStr) {
  if (!dateStr || typeof dateStr !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) return null;
  return dateStr.slice(5);
}

function parseTimeToMinutes(timeStr) {
  if (!timeStr || typeof timeStr !== 'string') return null;
  const [hourRaw, minuteRaw] = timeStr.split(':');
  const hour = Number(hourRaw);
  const minute = Number(minuteRaw);
  if (Number.isNaN(hour) || Number.isNaN(minute)) return null;
  return hour * 60 + minute;
}

function isSessionTimeOverlap(startA, endA, startB, endB) {
  const startAMinutes = parseTimeToMinutes(startA);
  const endAMinutes = parseTimeToMinutes(endA);
  const startBMinutes = parseTimeToMinutes(startB);
  const endBMinutes = parseTimeToMinutes(endB);

  if (
    startAMinutes === null ||
    endAMinutes === null ||
    startBMinutes === null ||
    endBMinutes === null
  ) {
    return false;
  }

  return startAMinutes < endBMinutes && startBMinutes < endAMinutes;
}

function inferScheduleExceptionType(session) {
  if (session?.is_makeup) return 'makeup';
  const notes = (session?.notes || '').toLowerCase();
  if (notes.startsWith('bá» qua:') || notes.startsWith('bo qua:')) return 'skip';
  if (notes.startsWith('dá»i lá»‹ch:') || notes.startsWith('doi lich:')) return 'reschedule';
  return null;
}

function normalizeClassStatus(status) {
  const normalized = String(status || '').toLowerCase();
  if (normalized === 'active') return 'ongoing';
  if (['ongoing', 'upcoming', 'completed', 'cancelled', 'paused'].includes(normalized)) {
    return normalized;
  }
  return 'upcoming';
}

function getClassOperationalRiskLevel(summary) {
  if (!summary) return 'low';
  if ((summary.conflictSessions || 0) > 0) return 'high';
  if ((summary.substitutedSessions || 0) > 0 || (summary.holidaySessions || 0) > 0) return 'medium';
  return 'low';
}

