// Import nhiÃ¡Â»Âu lÃ¡Â»â€ºp hÃ¡Â»Âc tÃ¡Â»Â« file
// ========================================
app.post('/api/admin/classes/import', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { classes: classesData } = req.body;

    if (!classesData || !Array.isArray(classesData) || classesData.length === 0) {
      return res.status(400).json({
        success: false,
        message: 'DÃ¡Â»Â¯ liÃ¡Â»â€¡u import khÃƒÂ´ng hÃ¡Â»Â£p lÃ¡Â»â€¡'
      });
    }

    console.log(`Ã°Å¸â€œÂ¥ Admin ${req.user.email} import ${classesData.length} lÃ¡Â»â€ºp hÃ¡Â»Âc`);

    // Fetch lookup data
    const [coursesRes, teachersRes, centersRes, roomsRes] = await Promise.all([
      supabase.from('courses').select('id, code, name'),
      supabase.from('users').select('id, email, full_name').eq('role_id', '7d0897c4-4e72-480e-97b4-86770b0b9542'),
      supabase.from('centers').select('id, code, name'),
      supabase.from('rooms').select('id, name, center_id')
    ]);

    const courses = coursesRes.data || [];
    const teachers = teachersRes.data || [];
    const centers = centersRes.data || [];
    const rooms = roomsRes.data || [];

    // Maps for quick lookup
    const courseByCode = new Map(courses.map(c => [c.code?.toLowerCase(), c]));
    const teacherByEmail = new Map(teachers.map(t => [t.email?.toLowerCase(), t]));
    const centerByCode = new Map(centers.map(c => [c.code?.toLowerCase(), c]));

    const results = {
      success: 0,
      failed: 0,
      errors: [],
      created: []
    };

    // Process each class
    for (let i = 0; i < classesData.length; i++) {
      const row = classesData[i];
      const rowNum = i + 1;

      try {
        // Validate and lookup course
        const course = courseByCode.get(row.course_code?.toLowerCase());
        if (!course) {
          results.failed++;
          results.errors.push({
            row: rowNum,
            error: `KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y khÃƒÂ³a hÃ¡Â»Âc vÃ¡Â»â€ºi mÃƒÂ£: ${row.course_code}`
          });
          continue;
        }

        // Lookup teacher (optional)
        let teacher = null;
        if (row.teacher_email) {
          teacher = teacherByEmail.get(row.teacher_email?.toLowerCase());
          if (!teacher) {
            results.failed++;
            results.errors.push({
              row: rowNum,
              error: `KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y giÃƒÂ¡o viÃƒÂªn vÃ¡Â»â€ºi email: ${row.teacher_email}`
            });
            continue;
          }
        }

        // Lookup center (optional, use first if not specified)
        let center = null;
        if (row.center_code) {
          center = centerByCode.get(row.center_code?.toLowerCase());
          if (!center) {
            results.failed++;
            results.errors.push({
              row: rowNum,
              error: `KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y trung tÃƒÂ¢m vÃ¡Â»â€ºi mÃƒÂ£: ${row.center_code}`
            });
            continue;
          }
        } else if (centers.length > 0) {
          center = centers[0]; // Default to first center
        }

        // Lookup room (optional)
        let room = null;
        if (row.room_name && center) {
          room = rooms.find(r =>
            r.name?.toLowerCase() === row.room_name?.toLowerCase() &&
            r.center_id === center.id
          );
        }

        // Generate class code if not provided
        let code = row.code;
        if (!code) {
          const randomNum = Math.floor(100000 + Math.random() * 900000);
          code = `CLS-${randomNum}`;
        }

        // Check for duplicate code
        const { data: existing } = await supabase
          .from('classes')
          .select('id')
          .eq('code', code)
          .single();

        if (existing) {
          results.failed++;
          results.errors.push({
            row: rowNum,
            error: `MÃƒÂ£ lÃ¡Â»â€ºp ${code} Ã„â€˜ÃƒÂ£ tÃ¡Â»â€œn tÃ¡ÂºÂ¡i`
          });
          continue;
        }

        // Validate status
        const validStatuses = ['upcoming', 'ongoing', 'completed', 'cancelled'];
        const status = validStatuses.includes(row.status?.toLowerCase())
          ? row.status.toLowerCase()
          : 'upcoming';

        // Insert class
        const { data: newClass, error: insertError } = await supabase
          .from('classes')
          .insert({
            code,
            name: row.name,
            course_id: course.id,
            teacher_id: teacher?.id || null,
            center_id: center?.id,
            room_id: room?.id || null,
            start_date: row.start_date || null,
            end_date: row.end_date || null,
            max_students: parseInt(row.max_students) || 20,
            status,
            schedule: []
          })
          .select()
          .single();

        if (insertError) {
          results.failed++;
          results.errors.push({
            row: rowNum,
            error: `LÃ¡Â»â€”i tÃ¡ÂºÂ¡o lÃ¡Â»â€ºp: ${insertError.message}`
          });
          continue;
        }

        results.success++;
        results.created.push({
          id: newClass.id,
          code: newClass.code,
          name: newClass.name
        });

      } catch (rowError) {
        results.failed++;
        results.errors.push({
          row: rowNum,
          error: rowError.message
        });
      }
    }

    console.log(`Ã¢Å“â€¦ Import kÃ¡ÂºÂ¿t quÃ¡ÂºÂ£: ${results.success} thÃƒÂ nh cÃƒÂ´ng, ${results.failed} thÃ¡ÂºÂ¥t bÃ¡ÂºÂ¡i`);

    res.json({
      success: true,
      ...results
    });

  } catch (error) {
    console.error('Error importing classes:', error);
    next(error);
  }
});

// CÃ¡ÂºÂ­p nhÃ¡ÂºÂ­t mÃ¡Â»â„¢t session (Ã„â€˜Ã¡Â»â€¢i GV, Ã„â€˜Ã¡Â»â€¢i status, etc.)
app.put('/api/admin/sessions/:id', requireAuth, async (req, res, next) => {
  try {
    const { id } = req.params;
    const updates = req.body;

    // Let the dedicated bulk route handle /api/admin/sessions/bulk
    if (id === 'bulk') {
      return next();
    }

    // KiÃ¡Â»Æ’m tra session cÃƒÂ³ bÃ¡Â»â€¹ lock khÃƒÂ´ng
    const { data: session, error: sessionError } = await supabase
      .from('sessions')
      .select('is_locked, class_id, session_date, start_time')
      .eq('id', id)
      .single();

    if (sessionError) throw sessionError;
    if (!session) {
      return res.status(404).json({ success: false, message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y buÃ¡Â»â€¢i hÃ¡Â»Âc' });
    }

    if (session?.is_locked) {
      return res.status(400).json({
        success: false,
        message: 'BuÃ¡Â»â€¢i hÃ¡Â»Âc Ã„â€˜ÃƒÂ£ Ã„â€˜Ã†Â°Ã¡Â»Â£c khÃƒÂ³a sÃ¡Â»â€¢, khÃƒÂ´ng thÃ¡Â»Æ’ sÃ¡Â»Â­a'
      });
    }


    // Block completing future sessions
    if (updates.status === 'completed' && session.session_date && session.start_time) {
      const sessionStart = new Date(`${session.session_date}T${session.start_time}`);
      if (sessionStart > new Date()) {
        return res.status(400).json({
          success: false,
          message: 'Không thể hoàn thành buổi học chưa diễn ra'
        });
      }
    }

    // KhÃƒÂ´ng cho sÃ¡Â»Â­a cÃƒÂ¡c trÃ†Â°Ã¡Â»Âng quan trÃ¡Â»Âng
    delete updates.is_locked;
    delete updates.payroll_id;
    delete updates.class_id;

    // XÃ¡Â»Â­ lÃƒÂ½ Ã„â€˜Ã¡ÂºÂ·c biÃ¡Â»â€¡t cho room_id - kiÃ¡Â»Æ’m tra xem cÃ¡Â»â„¢t cÃƒÂ³ tÃ¡Â»â€œn tÃ¡ÂºÂ¡i khÃƒÂ´ng
    const roomIdUpdate = updates.room_id;
    delete updates.room_id; // XÃƒÂ³a khÃ¡Â»Âi updates chung Ã„â€˜Ã¡Â»Æ’ xÃ¡Â»Â­ lÃƒÂ½ riÃƒÂªng

    // Update cÃƒÂ¡c trÃ†Â°Ã¡Â»Âng thÃƒÂ´ng thÃ†Â°Ã¡Â»Âng
    const safeUpdates = { ...updates, updated_at: new Date().toISOString() };

    // ChÃ¡Â»â€° thÃƒÂªm room_id nÃ¡ÂºÂ¿u cÃƒÂ³ yÃƒÂªu cÃ¡ÂºÂ§u Ã„â€˜Ã¡Â»â€¢i phÃƒÂ²ng
    if (roomIdUpdate !== undefined) {
      safeUpdates.room_id = roomIdUpdate;
    }

    const { data, error } = await supabase
      .from('sessions')
      .update(safeUpdates)
      .eq('id', id)
      .select()
      .single();

    if (error) {
      // NÃ¡ÂºÂ¿u lÃ¡Â»â€”i lÃƒÂ  do cÃ¡Â»â„¢t room_id khÃƒÂ´ng tÃ¡Â»â€œn tÃ¡ÂºÂ¡i
      if (error.code === 'PGRST204' && error.message?.includes('room_id')) {
        return res.status(400).json({
          success: false,
          message: 'ChÃ¡Â»Â©c nÃ„Æ’ng Ã„â€˜Ã¡Â»â€¢i phÃƒÂ²ng tÃ¡Â»Â«ng buÃ¡Â»â€¢i chÃ†Â°a Ã„â€˜Ã†Â°Ã¡Â»Â£c kÃƒÂ­ch hoÃ¡ÂºÂ¡t. Vui lÃƒÂ²ng chÃ¡ÂºÂ¡y migration 13_add_room_to_sessions.sql'
        });
      }
      throw error;
    }

    res.json({ success: true, data });
  } catch (error) {
    console.error('Error updating session:', error);
    next(error);
  }
});

// ========================================
// Bulk update nhiÃ¡Â»Âu sessions cÃƒÂ¹ng lÃƒÂºc
// ========================================
app.put('/api/admin/sessions/bulk', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { sessionIds, action, updates } = req.body;

    if (!sessionIds || !Array.isArray(sessionIds) || sessionIds.length === 0) {
      return res.status(400).json({
        success: false,
        message: 'Danh sách buổi học không hợp lệ'
      });
    }

    // Support both action-based and updates-based bulk operations
    if (action && ['complete', 'cancel'].includes(action)) {
      // Action-based: complete or cancel
      console.log(`📦 Admin ${req.user.email} bulk ${action} ${sessionIds.length} sessions`);

      const { data: sessions, error: fetchError } = await supabase
        .from('sessions')
        .select('id, status, is_locked, session_date, start_time, classes(id, center_id)')
        .in('id', sessionIds);

      if (fetchError) throw fetchError;
      if (!sessions || sessions.length === 0) {
        return res.status(404).json({ success: false, message: 'Không tìm thấy buổi học nào' });
      }

      // Permission check
      const userRole = req.user.roleCode;
      const userCenterId = req.user.centerId;
      for (const session of sessions) {
        const sessionCenterId = session.classes?.center_id;
        if (userRole !== 'SUPER_ADMIN' && sessionCenterId !== userCenterId) {
          return res.status(403).json({
            success: false,
            message: 'Bạn không có quyền thao tác buổi học thuộc trung tâm khác'
          });
        }
      }

      // Filter out locked sessions
      const lockedSessions = sessions.filter(s => s.is_locked);
      const editableSessions = sessions.filter(s => !s.is_locked);

      if (editableSessions.length === 0) {
        return res.status(400).json({
          success: false,
          message: 'Tất cả buổi học đã bị khóa, không thể thay đổi',
          lockedCount: lockedSessions.length
        });
      }

      let toUpdate = editableSessions;
      let skippedByStatus = [];

      if (action === 'complete') {
        const now = new Date();
        toUpdate = editableSessions.filter(s => {
          if (s.status !== 'scheduled' && s.status !== 'upcoming') return false;
          // Block completing future sessions
          if (s.session_date && s.start_time) {
            const sessionStart = new Date(`${s.session_date}T${s.start_time}`);
            if (sessionStart > now) return false;
          }
          return true;
        });
        skippedByStatus = editableSessions.filter(s => !toUpdate.find(t => t.id === s.id));
      } else if (action === 'cancel') {
        toUpdate = editableSessions.filter(s => ['scheduled', 'upcoming'].includes(s.status));
        skippedByStatus = editableSessions.filter(s => !['scheduled', 'upcoming'].includes(s.status));
      }

      if (toUpdate.length === 0) {
        return res.status(400).json({
          success: false,
          message: `Không có buổi học nào có thể ${action === 'complete' ? 'hoàn thành' : 'hủy'}`,
          lockedCount: lockedSessions.length,
          skippedByStatus: skippedByStatus.length
        });
      }

      const newStatus = action === 'complete' ? 'completed' : 'cancelled';
      const idsToUpdate = toUpdate.map(s => s.id);

      const { error: updateError } = await supabase
        .from('sessions')
        .update({ status: newStatus, updated_at: new Date().toISOString() })
        .in('id', idsToUpdate);

      if (updateError) throw updateError;

      console.log(`✅ Bulk ${action}: ${idsToUpdate.length} sessions updated`);

      return res.json({
        success: true,
        updatedCount: idsToUpdate.length,
        lockedCount: lockedSessions.length,
        skippedByStatus: skippedByStatus.length,
        updatedIds: idsToUpdate,
        message: `Đã ${action === 'complete' ? 'hoàn thành' : 'hủy'} ${idsToUpdate.length} buổi học`
      });
    }

    // Updates-based: generic bulk update
    if (!updates || Object.keys(updates).length === 0) {
      return res.status(400).json({
        success: false,
        message: 'Không có thay đổi nào được gửi'
      });
    }

    console.log(`📝 Admin ${req.user.email} bulk update ${sessionIds.length} sessions:`, updates);

    const { data: sessions, error: fetchError } = await supabase
      .from('sessions')
      .select('id, is_locked')
      .in('id', sessionIds);

    if (fetchError) throw fetchError;

    const lockedSessions = sessions?.filter(s => s.is_locked) || [];
    if (lockedSessions.length > 0) {
      return res.status(400).json({
        success: false,
        message: `${lockedSessions.length} buổi học đã bị khóa sổ, không thể sửa`
      });
    }

    const safeUpdates = { ...updates };
    delete safeUpdates.is_locked;
    delete safeUpdates.payroll_id;
    delete safeUpdates.class_id;
    delete safeUpdates.id;
    safeUpdates.updated_at = new Date().toISOString();

    const { data, error: updateError } = await supabase
      .from('sessions')
      .update(safeUpdates)
      .in('id', sessionIds)
      .select();

    if (updateError) throw updateError;

    console.log(`✅ Đã cập nhật ${data?.length || 0} buổi học`);

    res.json({
      success: true,
      message: `Đã cập nhật ${data?.length || 0} buổi học`,
      updated: data?.length || 0,
      data
    });
  } catch (error) {
    console.error('Error bulk updating sessions:', error);
    next(error);
  }
});

// LÃ¡ÂºÂ¥y danh sÃƒÂ¡ch GV rÃ¡ÂºÂ£nh vÃƒÂ o mÃ¡Â»â„¢t khung giÃ¡Â»Â cÃ¡Â»Â¥ thÃ¡Â»Æ’
app.get('/api/admin/sessions/:sessionId/available-teachers', requireAuth, async (req, res, next) => {
  try {
    const { sessionId } = req.params;

    // LÃ¡ÂºÂ¥y thÃƒÂ´ng tin session hiÃ¡Â»â€¡n tÃ¡ÂºÂ¡i
    const { data: session, error: sessionError } = await supabase
      .from('sessions')
      .select('session_date, start_time, end_time, teacher_id, classes(center_id)')
      .eq('id', sessionId)
      .single();

    if (sessionError) throw sessionError;
    if (!session) return res.status(404).json({ success: false, message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y buÃ¡Â»â€¢i hÃ¡Â»Âc' });

    // LÃ¡ÂºÂ¥y tÃ¡ÂºÂ¥t cÃ¡ÂºÂ£ giÃƒÂ¡o viÃƒÂªn
    const { data: teachers, error: teachersError } = await supabase
      .from('users')
      .select('id, full_name, email, avatar_url')
      .eq('role_id', (await supabase.from('roles').select('id').eq('code', 'TEACHER').single()).data?.id);

    if (teachersError) throw teachersError;

    // LÃ¡ÂºÂ¥y cÃƒÂ¡c sessions trÃƒÂ¹ng giÃ¡Â»Â
    const { data: busySessions } = await supabase
      .from('sessions')
      .select('teacher_id')
      .eq('session_date', session.session_date)
      .neq('id', sessionId)
      .neq('status', 'cancelled')
      .or(`and(start_time.lt.${session.end_time},end_time.gt.${session.start_time})`);

    const busyTeacherIds = new Set((busySessions || []).map(s => s.teacher_id).filter(Boolean));

    // Ã„ÂÃƒÂ¡nh dÃ¡ÂºÂ¥u GV nÃƒÂ o Ã„â€˜ang bÃ¡ÂºÂ­n
    const result = (teachers || []).map(t => ({
      ...t,
      isBusy: busyTeacherIds.has(t.id),
      isCurrent: t.id === session.teacher_id
    }));

    res.json({
      success: true,
      data: result,
      sessionInfo: {
        date: session.session_date,
        startTime: session.start_time,
        endTime: session.end_time
      }
    });
  } catch (error) {
    console.error('Error fetching available teachers:', error);
    next(error);
  }
});

// LÃ¡ÂºÂ¥y danh sÃƒÂ¡ch phÃƒÂ²ng trÃ¡Â»â€˜ng vÃƒÂ o mÃ¡Â»â„¢t khung giÃ¡Â»Â cÃ¡Â»Â¥ thÃ¡Â»Æ’
app.get('/api/admin/sessions/:sessionId/available-rooms', requireAuth, async (req, res, next) => {
  try {
    const { sessionId } = req.params;

    // LÃ¡ÂºÂ¥y thÃƒÂ´ng tin session hiÃ¡Â»â€¡n tÃ¡ÂºÂ¡i (session khÃƒÂ´ng cÃƒÂ³ room_id, lÃ¡ÂºÂ¥y tÃ¡Â»Â« class)
    const { data: session, error: sessionError } = await supabase
      .from('sessions')
      .select('id, session_date, start_time, end_time, class_id, classes(id, center_id, room_id, rooms(id, name))')
      .eq('id', sessionId)
      .single();

    if (sessionError) {
      console.error('Session error:', sessionError);
      throw sessionError;
    }
    if (!session) return res.status(404).json({ success: false, message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y buÃ¡Â»â€¢i hÃ¡Â»Âc' });

    // LÃ¡ÂºÂ¥y tÃ¡ÂºÂ¥t cÃ¡ÂºÂ£ phÃƒÂ²ng hÃ¡Â»Âc (cÃƒÂ¹ng center nÃ¡ÂºÂ¿u cÃ¡ÂºÂ§n)
    let roomQuery = supabase.from('rooms').select('id, name, code, capacity, center_id, centers(name)');
    if (session.classes?.center_id) {
      roomQuery = roomQuery.eq('center_id', session.classes.center_id);
    }
    const { data: rooms, error: roomsError } = await roomQuery;

    if (roomsError) {
      console.error('Rooms error:', roomsError);
      throw roomsError;
    }

    // LÃ¡ÂºÂ¥y cÃƒÂ¡c sessions trÃƒÂ¹ng giÃ¡Â»Â trong cÃƒÂ¹ng ngÃƒÂ y
    const { data: busySessions, error: busyError } = await supabase
      .from('sessions')
      .select('id, class_id')
      .eq('session_date', session.session_date)
      .neq('id', sessionId)
      .neq('status', 'cancelled');

    if (busyError) {
      console.error('Busy sessions error:', busyError);
    }

    // LÃ¡ÂºÂ¥y room cÃ¡Â»Â§a cÃƒÂ¡c class cÃƒÂ³ session trÃƒÂ¹ng ngÃƒÂ y
    const busyRoomIds = new Set();
    if (busySessions && busySessions.length > 0) {
      const classIds = [...new Set(busySessions.map(s => s.class_id).filter(Boolean))];
      if (classIds.length > 0) {
        const { data: busyClasses } = await supabase
          .from('classes')
          .select('id, room_id')
          .in('id', classIds);

        (busyClasses || []).forEach(c => {
          if (c.room_id) busyRoomIds.add(c.room_id);
        });
      }
    }

    const currentRoomId = session.classes?.room_id;

    // Ã„ÂÃƒÂ¡nh dÃ¡ÂºÂ¥u phÃƒÂ²ng nÃƒÂ o Ã„â€˜ang bÃ¡ÂºÂ­n
    const result = (rooms || []).map(r => ({
      ...r,
      isBusy: busyRoomIds.has(r.id) && r.id !== currentRoomId,
      isCurrent: r.id === currentRoomId
    }));

    res.json({
      success: true,
      data: result,
      sessionInfo: {
        date: session.session_date,
        startTime: session.start_time,
        endTime: session.end_time,
        currentRoom: session.classes?.rooms?.name || null
      }
    });
  } catch (error) {
    console.error('Error fetching available rooms:', error);
    next(error);
  }
});

