// Utility: Parse schedule tÃ¡Â»Â« nhiÃ¡Â»Âu format khÃƒÂ¡c nhau
function parseScheduleData(schedule) {
  if (!schedule) return { days: [], startTime: '18:00', endTime: '20:00' };

  // Format 1: JSON array [{"day":2,"start":"18:00","end":"20:00"},...]
  if (typeof schedule === 'string' && schedule.startsWith('[')) {
    try {
      const parsed = JSON.parse(schedule);
      if (Array.isArray(parsed) && parsed.length > 0) {
        // day: 2=T2, 3=T3, ..., 7=T7, 8=CN (theo format cÃ¡Â»Â§a frontend)
        // CÃ¡ÂºÂ§n convert sang dayOfWeek: 0=CN, 1=T2, 2=T3, ...
        const dayMapping = { 2: 1, 3: 2, 4: 3, 5: 4, 6: 5, 7: 6, 8: 0 };
        const days = parsed.map(s => dayMapping[s.day]).filter(d => d !== undefined);
        return {
          days,
          startTime: parsed[0]?.start || '18:00',
          endTime: parsed[0]?.end || '20:00'
        };
      }
    } catch (e) {
      console.log('Error parsing JSON schedule:', e);
    }
  }

  // Format 2: Array object (already parsed)
  if (Array.isArray(schedule) && schedule.length > 0) {
    const dayMapping = { 2: 1, 3: 2, 4: 3, 5: 4, 6: 5, 7: 6, 8: 0 };
    const days = schedule.map(s => dayMapping[s.day]).filter(d => d !== undefined);
    return {
      days,
      startTime: schedule[0]?.start || '18:00',
      endTime: schedule[0]?.end || '20:00'
    };
  }

  // Format 3: String "T2-T4-T6"
  if (typeof schedule === 'string') {
    const dayMap = { 'T2': 1, 'T3': 2, 'T4': 3, 'T5': 4, 'T6': 5, 'T7': 6, 'CN': 0 };
    const days = schedule.split('-').map(d => dayMap[d.trim()]).filter(d => d !== undefined);
    return { days, startTime: '18:00', endTime: '20:00' };
  }

  return { days: [], startTime: '18:00', endTime: '20:00' };
}

// Utility: Sinh danh sÃƒÂ¡ch cÃƒÂ¡c buÃ¡Â»â€¢i hÃ¡Â»Âc tÃ¡Â»Â« lÃ¡Â»â€¹ch lÃ¡Â»â€ºp
function generateSessions(startDate, endDate, schedule) {
  const sessions = [];
  if (!startDate || !endDate || !schedule) return sessions;

  const { days: scheduleDays, startTime, endTime } = parseScheduleData(schedule);
  if (scheduleDays.length === 0) return sessions;

  // Parse dates as local time to avoid timezone issues
  const [startYear, startMonth, startDay] = startDate.split('-').map(Number);
  const [endYear, endMonth, endDay] = endDate.split('-').map(Number);
  const start = new Date(startYear, startMonth - 1, startDay);
  const end = new Date(endYear, endMonth - 1, endDay);
  let sessionNumber = 1;

  // Danh sÃƒÂ¡ch ngÃƒÂ y nghÃ¡Â»â€° lÃ¡Â»â€¦ ViÃ¡Â»â€¡t Nam 2025-2026
  const holidays = [
    '2025-01-01', // TÃ¡ÂºÂ¿t DÃ†Â°Ã†Â¡ng lÃ¡Â»â€¹ch
    '2025-01-28', '2025-01-29', '2025-01-30', '2025-01-31', '2025-02-01', '2025-02-02', '2025-02-03', // TÃ¡ÂºÂ¿t NguyÃƒÂªn Ã„â€˜ÃƒÂ¡n
    '2025-04-30', // GiÃ¡ÂºÂ£i phÃƒÂ³ng miÃ¡Â»Ân Nam
    '2025-05-01', // QuÃ¡Â»â€˜c tÃ¡ÂºÂ¿ Lao Ã„â€˜Ã¡Â»â„¢ng
    '2025-09-02', // QuÃ¡Â»â€˜c khÃƒÂ¡nh
  ];

  for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
    const dayOfWeek = d.getDay(); // 0=CN, 1=T2, 2=T3, ...
    // Format date as YYYY-MM-DD without timezone conversion
    const dateStr = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;

    if (scheduleDays.includes(dayOfWeek) && !holidays.includes(dateStr)) {
      const today = new Date();
      today.setHours(0, 0, 0, 0);
      const sessionDate = new Date(d);
      sessionDate.setHours(0, 0, 0, 0);

      let status = 'upcoming';
      if (sessionDate < today) {
        status = 'completed';
      } else if (sessionDate.getTime() === today.getTime()) {
        status = 'today';
      }

      sessions.push({
        session_number: sessionNumber,
        date: dateStr,
        day_of_week: dayOfWeek,
        start_time: startTime,
        end_time: endTime,
        status: status
      });
      sessionNumber++;
    }
  }

  return sessions;
}

// Utility: TÃƒÂªn thÃ¡Â»Â© tiÃ¡ÂºÂ¿ng ViÃ¡Â»â€¡t
function getDayName(dayOfWeek) {
  const days = ['ChÃ¡Â»Â§ nhÃ¡ÂºÂ­t', 'ThÃ¡Â»Â© 2', 'ThÃ¡Â»Â© 3', 'ThÃ¡Â»Â© 4', 'ThÃ¡Â»Â© 5', 'ThÃ¡Â»Â© 6', 'ThÃ¡Â»Â© 7'];
  return days[dayOfWeek];
}

// API: LÃ¡ÂºÂ¥y danh sÃƒÂ¡ch buÃ¡Â»â€¢i hÃ¡Â»Âc cÃ¡Â»Â§a mÃ¡Â»â„¢t lÃ¡Â»â€ºp
app.get('/api/classes/:id/sessions', requireAuth, async (req, res, next) => {
  try {
    const { id } = req.params;

    // LÃ¡ÂºÂ¥y thÃƒÂ´ng tin lÃ¡Â»â€ºp hÃ¡Â»Âc
    const { data: classData, error: classError } = await supabase
      .from('classes')
      .select(`
        id, code, name, schedule, start_date, end_date,
        teacher_id,
        teacher:users!classes_teacher_id_fkey(id, full_name, avatar_url)
      `)
      .eq('id', id)
      .single();

    if (classError) throw classError;
    if (!classData) {
      return res.status(404).json({ success: false, message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y lÃ¡Â»â€ºp hÃ¡Â»Âc' });
    }

    // Sinh danh sÃƒÂ¡ch buÃ¡Â»â€¢i hÃ¡Â»Âc
    const sessions = generateSessions(
      classData.start_date,
      classData.end_date,
      classData.schedule
    );

    // LÃ¡ÂºÂ¥y thÃƒÂ´ng tin Ã„â€˜iÃ¡Â»Æ’m danh Ã„â€˜ÃƒÂ£ cÃƒÂ³
    const { data: attendanceData, error: attendanceError } = await supabase
      .from('attendance')
      .select(`
        session_date,
        status,
        enrollment_id
      `)
      .eq('enrollment_id', supabase.rpc('get_enrollment_ids_by_class', { class_id: id }));

    // Ã„ÂÃ¡ÂºÂ¿m sÃ¡Â»â€˜ hÃ¡Â»Âc viÃƒÂªn Ã„â€˜ÃƒÂ£ Ã„â€˜iÃ¡Â»Æ’m danh cho mÃ¡Â»â€”i buÃ¡Â»â€¢i
    const sessionDates = sessions.map(s => s.date);

    const { data: attendanceSummary, error: summaryError } = await supabase
      .from('attendance')
      .select(`
        session_date,
        status,
        enrollments!inner(class_id)
      `)
      .eq('enrollments.class_id', id)
      .in('session_date', sessionDates);

    // TÃƒÂ­nh tÃ¡Â»â€¢ng sÃ¡Â»â€˜ hÃ¡Â»Âc viÃƒÂªn trong lÃ¡Â»â€ºp
    const { count: totalStudents } = await supabase
      .from('enrollments')
      .select('id', { count: 'exact' })
      .eq('class_id', id)
      .eq('status', 'active');

    // Group attendance by date
    const attendanceByDate = {};
    if (attendanceSummary) {
      attendanceSummary.forEach(att => {
        if (!attendanceByDate[att.session_date]) {
          attendanceByDate[att.session_date] = { present: 0, absent: 0, late: 0, total: 0 };
        }
        attendanceByDate[att.session_date].total++;
        if (att.status === 'present') attendanceByDate[att.session_date].present++;
        else if (att.status === 'absent') attendanceByDate[att.session_date].absent++;
        else if (att.status === 'late') attendanceByDate[att.session_date].late++;
      });
    }

    // Enrich sessions with attendance summary
    const enrichedSessions = sessions.map(session => ({
      ...session,
      day_name: getDayName(session.day_of_week),
      teacher: classData.teacher,
      attendance_summary: attendanceByDate[session.date] || null,
      total_students: totalStudents || 0,
      is_marked: !!attendanceByDate[session.date]
    }));

    res.json({
      success: true,
      data: {
        class_info: {
          id: classData.id,
          code: classData.code,
          name: classData.name,
          schedule: classData.schedule,
          teacher: classData.teacher
        },
        sessions: enrichedSessions,
        total_sessions: sessions.length,
        completed_sessions: sessions.filter(s => s.status === 'completed').length
      }
    });

  } catch (error) {
    console.error('Error fetching sessions:', error);
    next(error);
  }
});

// API: LÃ¡ÂºÂ¥y bÃ¡ÂºÂ£ng Ã„â€˜iÃ¡Â»Æ’m danh cÃ¡Â»Â§a mÃ¡Â»â„¢t buÃ¡Â»â€¢i hÃ¡Â»Âc cÃ¡Â»Â¥ thÃ¡Â»Æ’
app.get('/api/classes/:id/attendance', requireAuth, async (req, res, next) => {
  try {
    const { id } = req.params;
    const { date } = req.query;

    if (!date) {
      return res.status(400).json({ success: false, message: 'ThiÃ¡ÂºÂ¿u tham sÃ¡Â»â€˜ date' });
    }

    // LÃ¡ÂºÂ¥y danh sÃƒÂ¡ch hÃ¡Â»Âc viÃƒÂªn trong lÃ¡Â»â€ºp
    const { data: enrollments, error: enrollError } = await supabase
      .from('enrollments')
      .select(`
        id,
        student_id,
        student:users!enrollments_student_id_fkey(
          id, full_name, email, phone, avatar_url
        )
      `)
      .eq('class_id', id)
      .eq('status', 'active')
      .order('created_at', { ascending: true });

    if (enrollError) throw enrollError;

    // LÃ¡ÂºÂ¥y Ã„â€˜iÃ¡Â»Æ’m danh Ã„â€˜ÃƒÂ£ cÃƒÂ³ cho ngÃƒÂ y nÃƒÂ y
    const enrollmentIds = enrollments.map(e => e.id);
    const { data: attendanceRecords, error: attError } = await supabase
      .from('attendance')
      .select('*')
      .eq('session_date', date)
      .in('enrollment_id', enrollmentIds);

    if (attError) throw attError;

    // Map attendance theo enrollment_id
    const attendanceMap = {};
    if (attendanceRecords) {
      attendanceRecords.forEach(att => {
        attendanceMap[att.enrollment_id] = att;
      });
    }

    // Merge data
    const students = enrollments.map(e => ({
      enrollment_id: e.id,
      student_id: e.student_id,
      full_name: e.student?.full_name || 'N/A',
      email: e.student?.email,
      phone: e.student?.phone,
      avatar_url: e.student?.avatar_url,
      attendance: attendanceMap[e.id] || null
    }));

    res.json({
      success: true,
      data: {
        date,
        students,
        total: students.length,
        marked: Object.keys(attendanceMap).length
      }
    });

  } catch (error) {
    console.error('Error fetching attendance:', error);
    next(error);
  }
});

// API: LÃ†Â°u/CÃ¡ÂºÂ­p nhÃ¡ÂºÂ­t Ã„â€˜iÃ¡Â»Æ’m danh hÃƒÂ ng loÃ¡ÂºÂ¡t
app.post('/api/attendance/mark', requireAuth, async (req, res, next) => {
  try {
    const { class_id, date, attendances, session_id } = req.body;
    const markedBy = req.user.id;

    if (!class_id || !date || !attendances || !Array.isArray(attendances)) {
      return res.status(400).json({
        success: false,
        message: 'ThiÃ¡ÂºÂ¿u thÃƒÂ´ng tin: class_id, date, attendances'
      });
    }

    console.log(`Ã°Å¸â€œÂ Ã„ÂiÃ¡Â»Æ’m danh lÃ¡Â»â€ºp ${class_id} ngÃƒÂ y ${date} bÃ¡Â»Å¸i user ${req.user.email}`);

    // Validate class exists
    const { data: classData, error: classError } = await supabase
      .from('classes')
      .select('id, code')
      .eq('id', class_id)
      .single();

    if (classError || !classData) {
      return res.status(404).json({ success: false, message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y lÃ¡Â»â€ºp hÃ¡Â»Âc' });
    }

    // TÃƒÂ­nh session_number
    const { data: sessionData } = await supabase
      .from('classes')
      .select('start_date, end_date, schedule')
      .eq('id', class_id)
      .single();

    const sessions = generateSessions(
      sessionData.start_date,
      sessionData.end_date,
      sessionData.schedule
    );
    const sessionInfo = sessions.find(s => s.date === date);
    const sessionNumber = sessionInfo?.session_number || null;

    // Upsert attendance records
    const upsertData = attendances.map(att => ({
      enrollment_id: att.enrollment_id,
      session_date: date,
      session_number: sessionNumber,
      status: att.status || 'present',
      notes: att.notes || null,
      marked_by: markedBy,
      marked_at: new Date().toISOString()
    }));

    const { data: result, error: upsertError } = await supabase
      .from('attendance')
      .upsert(upsertData, {
        onConflict: 'enrollment_id,session_date',
        ignoreDuplicates: false
      })
      .select();

    if (upsertError) throw upsertError;

    // Ã°Å¸â€Â¥ CÃ¡ÂºÂ­p nhÃ¡ÂºÂ­t session status thÃƒÂ nh 'completed' nÃ¡ÂºÂ¿u cÃƒÂ³ session_id
    if (session_id) {
      const { error: sessionUpdateError } = await supabase
        .from('sessions')
        .update({
          status: 'completed',
          updated_at: new Date().toISOString()
        })
        .eq('id', session_id);

      if (sessionUpdateError) {
        console.warn('Warning updating session status:', sessionUpdateError);
      } else {
        console.log(`Ã¢Å“â€¦ Session ${session_id} marked as completed`);
      }
    } else {
      // Fallback: tÃƒÂ¬m session theo class_id vÃƒÂ  date
      const { error: sessionUpdateError } = await supabase
        .from('sessions')
        .update({
          status: 'completed',
          updated_at: new Date().toISOString()
        })
        .eq('class_id', class_id)
        .eq('session_date', date);

      if (!sessionUpdateError) {
        console.log(`Ã¢Å“â€¦ Session for class ${class_id} on ${date} marked as completed`);
      }
    }

    // TÃƒÂ­nh summary
    const summary = {
      present: attendances.filter(a => a.status === 'present').length,
      absent: attendances.filter(a => a.status === 'absent').length,
      late: attendances.filter(a => a.status === 'late').length,
      total: attendances.length
    };

    console.log(`Ã¢Å“â€¦ Ã„ÂiÃ¡Â»Æ’m danh thÃƒÂ nh cÃƒÂ´ng: ${summary.present} cÃƒÂ³ mÃ¡ÂºÂ·t, ${summary.absent} vÃ¡ÂºÂ¯ng, ${summary.late} trÃ¡Â»â€¦`);

    AuditLogService.log({
      ...getAuditContext(req),
      centerId: getEffectiveCenterId(req),
      action: 'CREATE',
      tableName: 'attendance',
      recordId: null,
      newValues: { session_id: req.body.session_id }
    });

    res.json({
      success: true,
      message: `Ã„ÂÃƒÂ£ lÃ†Â°u Ã„â€˜iÃ¡Â»Æ’m danh ${summary.total} hÃ¡Â»Âc viÃƒÂªn`,
      data: {
        date,
        session_number: sessionNumber,
        summary,
        records: result
      }
    });

  } catch (error) {
    console.error('Error marking attendance:', error);
    next(error);
  }
});

