app.get('/api/dashboard/alerts', requireAuth, async (req, res, next) => {
  try {
    const { centerId } = req.query;
    const { effectiveCenterId } = getEffectiveCenterId(req.user, centerId);

    console.log(`Ã°Å¸â€œÅ  Dashboard alerts requested by ${req.user.email} | Center: ${effectiveCenterId || 'ALL'}`);

    const today = new Date().toISOString().split('T')[0];
    const alerts = {};
    let dataFreshness = 'fresh';

    // 1. Overdue Invoices
    let overdueQuery = supabase
      .from('invoices')
      .select(`
        id,
        invoice_code,
        final_amount,
        paid_amount,
        due_date,
        student:users!invoices_student_id_fkey (full_name),
        class:classes!inner (center_id)
      `)
      .in('status', ['pending', 'partial'])
      .lt('due_date', today);

    if (effectiveCenterId) {
      overdueQuery = overdueQuery.eq('class.center_id', effectiveCenterId);
    }

    const { data: overdueInvoices } = await overdueQuery;

    alerts.overdue_invoices = {
      data: (overdueInvoices || []).map(inv => {
        const daysOverdue = Math.floor((new Date() - new Date(inv.due_date)) / (1000 * 60 * 60 * 24));
        return {
          invoice_id: inv.id,
          invoice_number: inv.invoice_code,
          student_name: inv.student?.full_name || 'N/A',
          amount: (inv.final_amount || 0) - (inv.paid_amount || 0),
          days_overdue: daysOverdue
        };
      })
    };

    // 2. Classes Missing Schedule
    let missingScheduleQuery = supabase
      .from('classes')
      .select(`
        id,
        name,
        start_date,
        courses (title)
      `)
      .in('status', ['upcoming', 'ongoing']);

    if (effectiveCenterId) {
      missingScheduleQuery = missingScheduleQuery.eq('center_id', effectiveCenterId);
    }

    const { data: classes } = await missingScheduleQuery;

    // Check which classes have no sessions
    const classesWithoutSessions = [];
    if (classes && classes.length > 0) {
      for (const cls of classes) {
        const { count } = await supabase
          .from('sessions')
          .select('*', { count: 'exact', head: true })
          .eq('class_id', cls.id);

        if (count === 0) {
          classesWithoutSessions.push({
            class_id: cls.id,
            class_name: cls.name,
            course_name: cls.courses?.title || 'N/A',
            start_date: cls.start_date
          });
        }
      }
    }

    alerts.classes_missing_schedule = {
      data: classesWithoutSessions
    };

    // 3. Draft Invoices (old drafts)
    const draftThreshold = new Date();
    draftThreshold.setDate(draftThreshold.getDate() - 7); // 7 days ago

    let draftQuery = supabase
      .from('invoices')
      .select(`
        id,
        invoice_code,
        final_amount,
        created_at,
        student:users!invoices_student_id_fkey (full_name),
        class:classes!inner (center_id)
      `)
      .eq('status', 'draft')
      .lt('created_at', draftThreshold.toISOString());

    if (effectiveCenterId) {
      draftQuery = draftQuery.eq('class.center_id', effectiveCenterId);
    }

    const { data: draftInvoices } = await draftQuery;

    alerts.draft_invoices = {
      data: (draftInvoices || []).map(inv => {
        const daysInDraft = Math.floor((new Date() - new Date(inv.created_at)) / (1000 * 60 * 60 * 24));
        return {
          invoice_id: inv.id,
          invoice_number: inv.invoice_code,
          student_name: inv.student?.full_name || 'N/A',
          amount: inv.final_amount,
          days_in_draft: daysInDraft
        };
      })
    };

    // 4. Certificates Pending Approval
    let pendingCertificatesQuery = supabase
      .from('certificates')
      .select(`
        id,
        certificate_number,
        created_at,
        student:users!certificates_student_id_fkey(id, full_name, email),
        class:classes(id, name, center_id),
        course:courses(id, title),
        certificate_type_ref:certificate_types(id, code, name)
      `)
      .eq('status', 'pending_approval')
      .order('created_at', { ascending: false })
      .limit(10);

    if (effectiveCenterId) {
      pendingCertificatesQuery = pendingCertificatesQuery.eq('center_id', effectiveCenterId);
    }

    const { data: pendingCertificates, error: pendingCertificatesError } = await pendingCertificatesQuery;

    if (pendingCertificatesError) {
      dataFreshness = 'degraded';
      alerts.certificates_pending = {
        data: [],
        degraded: true,
        warning: 'KhÃƒÂ´ng thÃ¡Â»Æ’ tÃ¡ÂºÂ£i danh sÃƒÂ¡ch chÃ¡Â»Â©ng chÃ¡Â»â€° chÃ¡Â»Â duyÃ¡Â»â€¡t',
      };
    } else {
      alerts.certificates_pending = {
        data: (pendingCertificates || []).map((item) => ({
          certificate_id: item.id,
          certificate_number: item.certificate_number,
          student_id: item.student?.id || null,
          student_name: item.student?.full_name || 'N/A',
          class_id: item.class?.id || null,
          class_name: item.class?.name || item.course?.title || 'N/A',
          course_name: item.course?.title || null,
          certificate_type_name: item.certificate_type_ref?.name || item.certificate_type_ref?.code || 'ChÃ¡Â»Â©ng chÃ¡Â»â€°',
          requested_at: item.created_at,
        })),
      };
    }

    // Count total alerts
    const totalAlerts = Object.keys(alerts).reduce((sum, key) => {
      const alertData = alerts[key]?.data || [];
      return sum + (Array.isArray(alertData) ? alertData.length : 0);
    }, 0);

    res.json({
      success: true,
      data: {
        alerts,
        summary: {
          total: totalAlerts,
          types: Object.keys(alerts).length
        },
        centerId: effectiveCenterId
      }
    });
  } catch (error) {
    console.error('Error in dashboard alerts endpoint:', error);
    next(error);
  }
});

