/**
 * POST /api/admin/invoices/bulk-payment
 * Process bulk payment for multiple invoices
 * Body: {
 *   invoice_ids: [uuid, uuid, ...],
 *   payment_method: 'cash' | 'bank_transfer' | 'card' | 'momo' | 'vnpay',
 *   reference_code: string (optional, for bank transfers),
 *   notes: string (optional)
 * }
 * Ã°Å¸â€â€™ SUPER_ADMIN, CENTER_MANAGER
 */
app.post('/api/admin/invoices/bulk-payment', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { invoice_ids, payment_method, reference_code, notes } = req.body;
    const userId = req.user?.id;

    console.log('Ã°Å¸â€™Â³ Bulk payment request:', { invoice_ids, payment_method, userId });

    // Validate invoice_ids
    if (!invoice_ids || !Array.isArray(invoice_ids) || invoice_ids.length === 0) {
      return res.status(400).json({
        success: false,
        message: 'Vui lÃƒÂ²ng chÃ¡Â»Ân ÃƒÂ­t nhÃ¡ÂºÂ¥t mÃ¡Â»â„¢t hÃƒÂ³a Ã„â€˜Ã†Â¡n Ã„â€˜Ã¡Â»Æ’ thanh toÃƒÂ¡n'
      });
    }

    // Validate payment_method
    const validMethods = ['cash', 'bank_transfer', 'card', 'momo', 'vnpay'];
    if (!payment_method || !validMethods.includes(payment_method)) {
      return res.status(400).json({
        success: false,
        message: 'PhÃ†Â°Ã†Â¡ng thÃ¡Â»Â©c thanh toÃƒÂ¡n khÃƒÂ´ng hÃ¡Â»Â£p lÃ¡Â»â€¡'
      });
    }

    if (payment_method !== 'cash' && !reference_code) {
      return res.status(400).json({
        success: false,
        message: 'Thanh toÃƒÂ¡n khÃƒÂ´ng dÃƒÂ¹ng tiÃ¡Â»Ân mÃ¡ÂºÂ·t cÃ¡ÂºÂ§n mÃƒÂ£ tham chiÃ¡ÂºÂ¿u giao dÃ¡Â»â€¹ch'
      });
    }

    const results = {
      processed: 0,
      skipped: 0,
      failed: 0,
      details: []
    };

    // Process each invoice
    for (const invoiceId of invoice_ids) {
      try {
        // Get current invoice with remaining amount
        const { data: invoice, error: invoiceError } = await supabase
          .from('invoices')
          .select('id, invoice_code, final_amount, paid_amount, status, student_id')
          .eq('id', invoiceId)
          .single();

        if (invoiceError || !invoice) {
          results.failed++;
          results.details.push({
            invoice_id: invoiceId,
            status: 'failed',
            reason: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y hÃƒÂ³a Ã„â€˜Ã†Â¡n'
          });
          console.log(`Ã¢ÂÅ’ Invoice ${invoiceId}: Not found`);
          continue;
        }

        // Skip if already paid
        if (invoice.status === 'paid') {
          results.skipped++;
          results.details.push({
            invoice_id: invoiceId,
            invoice_code: invoice.invoice_code,
            status: 'skipped',
            reason: 'HÃƒÂ³a Ã„â€˜Ã†Â¡n Ã„â€˜ÃƒÂ£ thanh toÃƒÂ¡n Ã„â€˜Ã¡Â»Â§'
          });
          console.log(`Ã¢ÂÂ­Ã¯Â¸Â Invoice ${invoice.invoice_code}: Already paid, skipping`);
          continue;
        }

        // Skip if cancelled or refunded
        if (invoice.status === 'cancelled' || invoice.status === 'refunded') {
          results.skipped++;
          results.details.push({
            invoice_id: invoiceId,
            invoice_code: invoice.invoice_code,
            status: 'skipped',
            reason: `HÃƒÂ³a Ã„â€˜Ã†Â¡n Ã„â€˜ÃƒÂ£ ${invoice.status === 'cancelled' ? 'hÃ¡Â»Â§y' : 'hoÃƒÂ n tiÃ¡Â»Ân'}`
          });
          console.log(`Ã¢ÂÂ­Ã¯Â¸Â Invoice ${invoice.invoice_code}: ${invoice.status}, skipping`);
          continue;
        }

        // Calculate remaining amount
        const remainingAmount = (invoice.final_amount || 0) - (invoice.paid_amount || 0);

        if (remainingAmount <= 0) {
          results.skipped++;
          results.details.push({
            invoice_id: invoiceId,
            invoice_code: invoice.invoice_code,
            status: 'skipped',
            reason: 'KhÃƒÂ´ng cÃƒÂ²n sÃ¡Â»â€˜ tiÃ¡Â»Ân cÃ¡ÂºÂ§n thanh toÃƒÂ¡n'
          });
          continue;
        }

        // Determine verification status
        const verificationStatus = payment_method === 'cash' ? 'verified' : 'pending';
        const autoVerified = payment_method === 'cash';

        // Create payment record for remaining amount
        const { data: payment, error: paymentError } = await supabase
          .from('payments')
          .insert({
            invoice_id: invoiceId,
            amount: remainingAmount,
            payment_method,
            reference_code: reference_code || null,
            notes: notes ? `[Bulk Payment] ${notes}` : '[Bulk Payment]',
            received_by: userId,
            verification_status: verificationStatus,
            verified_by: autoVerified ? userId : null,
            verified_at: autoVerified ? new Date().toISOString() : null
          })
          .select()
          .single();

        if (paymentError) {
          results.failed++;
          results.details.push({
            invoice_id: invoiceId,
            invoice_code: invoice.invoice_code,
            status: 'failed',
            reason: paymentError.message
          });
          console.log(`Ã¢ÂÅ’ Invoice ${invoice.invoice_code}: Payment error - ${paymentError.message}`);
          continue;
        }

        // Get updated invoice (trigger should have updated paid_amount and status)
        const { data: updatedInvoice } = await supabase
          .from('invoices')
          .select('id, invoice_code, final_amount, paid_amount, status')
          .eq('id', invoiceId)
          .single();

        results.processed++;
        results.details.push({
          invoice_id: invoiceId,
          invoice_code: invoice.invoice_code,
          status: 'processed',
          payment_id: payment.id,
          amount_paid: remainingAmount,
          new_status: updatedInvoice?.status || 'paid',
          requires_verification: !autoVerified
        });
        console.log(`Ã¢Å“â€¦ Invoice ${invoice.invoice_code}: Paid ${remainingAmount.toLocaleString()}Ã„â€˜`);

      } catch (err) {
        results.failed++;
        results.details.push({
          invoice_id: invoiceId,
          status: 'failed',
          reason: err.message
        });
        console.error(`Ã¢ÂÅ’ Invoice ${invoiceId}: Error - ${err.message}`);
      }
    }

    console.log(`Ã°Å¸â€™Â³ Bulk payment complete: ${results.processed} processed, ${results.skipped} skipped, ${results.failed} failed`);

    res.json({
      success: true,
      message: `Ã„ÂÃƒÂ£ xÃ¡Â»Â­ lÃƒÂ½ ${results.processed} hÃƒÂ³a Ã„â€˜Ã†Â¡n${results.skipped > 0 ? `, bÃ¡Â»Â qua ${results.skipped}` : ''}${results.failed > 0 ? `, lÃ¡Â»â€”i ${results.failed}` : ''}`,
      data: results
    });

  } catch (error) {
    console.error('Ã¢ÂÅ’ Error processing bulk payment:', error);
    next(error);
  }
});

/**
 * GET /api/admin/invoices/overdue
 * Get list of overdue invoices with student contact info
 * Query: ?center_id=xxx&daysOverdueMin=1&daysOverdueMax=7&page=1&limit=20&sortBy=days_overdue&sortOrder=desc
 * Ã°Å¸â€â€™ SUPER_ADMIN, CENTER_MANAGER
 */
app.get('/api/admin/invoices/overdue', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const {
      center_id,
      daysOverdueMin,
      daysOverdueMax,
      sortBy = 'days_overdue',
      sortOrder = 'desc',
      page = 1,
      limit = 20
    } = req.query;

    // Use standard center scoping (consistent with rest of codebase)
    const { effectiveCenterId, error: permError } = getEffectiveCenterId(req.user, center_id);
    if (permError) {
      return res.status(403).json({ success: false, message: permError });
    }

    const pageNum = parseInt(page) || 1;
    const limitNum = Math.min(parseInt(limit) || 20, 100); // Cap at 100
    const offset = (pageNum - 1) * limitNum;

    // Calculate date thresholds from days overdue for SQL-level filtering
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    const todayStr = today.toISOString().split('T')[0];

    // daysOverdueMin=8 Ã¢â€ â€™ invoice must be at least 8 days overdue Ã¢â€ â€™ due_date <= today - 8
    let maxDueDate = todayStr; // Default: all overdue (due_date < today)
    if (daysOverdueMin && parseInt(daysOverdueMin) > 0) {
      const d = new Date(today);
      d.setDate(d.getDate() - parseInt(daysOverdueMin) + 1);
      maxDueDate = d.toISOString().split('T')[0];
    }

    // daysOverdueMax=14 Ã¢â€ â€™ invoice is at most 14 days overdue Ã¢â€ â€™ due_date >= today - 14
    let minDueDate = null;
    if (daysOverdueMax && parseInt(daysOverdueMax) > 0) {
      const d = new Date(today);
      d.setDate(d.getDate() - parseInt(daysOverdueMax));
      minDueDate = d.toISOString().split('T')[0];
    }

    console.log('Ã°Å¸â€œâ€¹ Fetching overdue invoices:', { effectiveCenterId, daysOverdueMin, daysOverdueMax, maxDueDate, minDueDate, pageNum, limitNum });

    // ---------- STATS QUERY (all overdue, no pagination, no day filter) ----------
    const statsSelect = effectiveCenterId
      ? 'due_date, final_amount, paid_amount, class:classes!inner(center_id)'
      : 'due_date, final_amount, paid_amount';

    let statsQuery = supabase
      .from('invoices')
      .select(statsSelect)
      .in('status', ['unpaid', 'partial', 'overdue'])
      .lt('due_date', todayStr);

    if (effectiveCenterId) {
      statsQuery = statsQuery.eq('class.center_id', effectiveCenterId);
    }

    const { data: allOverdue } = await statsQuery;

    // Compute global stats & severity breakdown
    const bySeverity = { low: 0, medium: 0, high: 0, critical: 0 };
    let totalAmount = 0;
    let totalDaysOverdue = 0;
    (allOverdue || []).forEach(inv => {
      const dueDate = new Date(inv.due_date);
      dueDate.setHours(0, 0, 0, 0);
      const daysOver = Math.floor((today - dueDate) / (1000 * 60 * 60 * 24));
      const remaining = (inv.final_amount || 0) - (inv.paid_amount || 0);
      totalAmount += remaining;
      totalDaysOverdue += daysOver;
      if (daysOver <= 7) bySeverity.low++;
      else if (daysOver <= 14) bySeverity.medium++;
      else if (daysOver <= 30) bySeverity.high++;
      else bySeverity.critical++;
    });
    const totalOverdue = (allOverdue || []).length;
    const avgDaysOverdue = totalOverdue > 0 ? Math.round(totalDaysOverdue / totalOverdue) : 0;

    // ---------- DATA QUERY (filtered, paginated) ----------
    // Use !inner join when center filter is active for proper SQL-level filtering
    const classJoin = effectiveCenterId ? 'class:classes!inner' : 'class:classes';
    const dataSelect = `
      id, invoice_code, invoice_type, amount, discount_amount, final_amount,
      paid_amount, status, due_date, created_at,
      student:users!invoices_student_id_fkey(id, full_name, email, phone),
      ${classJoin}(id, code, name, center_id, course:courses(id, title))
    `;

    let query = supabase
      .from('invoices')
      .select(dataSelect, { count: 'exact' })
      .in('status', ['unpaid', 'partial', 'overdue'])
      .lt('due_date', maxDueDate);

    // Apply day range filter at SQL level
    if (minDueDate) {
      query = query.gte('due_date', minDueDate);
    }

    // Center filter at SQL level via inner join
    if (effectiveCenterId) {
      query = query.eq('class.center_id', effectiveCenterId);
    }

    // Sorting
    if (sortBy === 'amount') {
      query = query.order('final_amount', { ascending: sortOrder === 'asc' });
    } else {
      // days_overdue Ã¢â€ â€™ sort by due_date (ascending = most overdue first when sortOrder=desc)
      query = query.order('due_date', { ascending: sortOrder !== 'desc' });
    }

    // Execute with pagination
    const { data: invoices, error, count } = await query
      .range(offset, offset + limitNum - 1);

    if (error) throw error;

    // Enrich with computed fields
    const enrichedInvoices = (invoices || []).map(invoice => {
      const dueDate = new Date(invoice.due_date);
      dueDate.setHours(0, 0, 0, 0);
      return {
        ...invoice,
        days_overdue: Math.floor((today - dueDate) / (1000 * 60 * 60 * 24)),
        remaining_amount: (invoice.final_amount || 0) - (invoice.paid_amount || 0)
      };
    });

    // Batch fetch last payment dates
    const invoiceIds = enrichedInvoices.map(inv => inv.id);
    let lastPayments = {};
    if (invoiceIds.length > 0) {
      const { data: payments } = await supabase
        .from('payments')
        .select('invoice_id, payment_date')
        .in('invoice_id', invoiceIds)
        .order('payment_date', { ascending: false });

      if (payments) {
        payments.forEach(p => {
          if (!lastPayments[p.invoice_id]) {
            lastPayments[p.invoice_id] = p.payment_date;
          }
        });
      }
    }

    const results = enrichedInvoices.map(invoice => ({
      ...invoice,
      last_payment_date: lastPayments[invoice.id] || null
    }));

    const total = count || 0;
    console.log(`Ã°Å¸â€œâ€¹ Found ${total} overdue invoices (page ${pageNum})`);

    // Response format matches frontend expectations
    res.json({
      success: true,
      invoices: results,
      stats: {
        totalOverdue: totalOverdue,
        totalAmount: totalAmount,
        avgDaysOverdue: avgDaysOverdue,
        bySeverity
      },
      pagination: {
        page: pageNum,
        limit: limitNum,
        total,
        totalPages: Math.ceil(total / limitNum)
      }
    });

  } catch (error) {
    console.error('Ã¢ÂÅ’ Error fetching overdue invoices:', error);
    next(error);
  }
});

