/**
 * GET /api/teacher/payroll/:id
 * Get payroll detail with sessions for the logged-in teacher
 * Ã°Å¸â€â€™ TEACHER only (can only view own payroll)
 */
app.get('/api/teacher/payroll/:id',
  requireAuth,
  requireRole(['TEACHER']),
  async (req, res, next) => {
    try {
      const { id } = req.params;
      const teacherId = req.user.id;

      console.log(`Ã°Å¸â€™Â° Teacher ${req.user.email} fetching payroll detail: ${id}`);

      // Fetch payroll and verify ownership
      const { data: payroll, error } = await supabase
        .from('payroll')
        .select(`
          id, period_month, period_year, status,
          base_salary, bonus, deduction, net_salary,
          total_sessions, total_hours,
          approved_at, notes, created_at, updated_at,
          payment_proof_url, paid_at, payment_method, payment_reference,
          approver:users!payroll_approved_by_fkey (
            id, full_name
          )
        `)
        .eq('id', id)
        .eq('teacher_id', teacherId) // Ensure teacher can only see own payroll
        .single();

      if (error || !payroll) {
        return res.status(404).json({
          success: false,
          message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y bÃ¡ÂºÂ£ng lÃ†Â°Ã†Â¡ng hoÃ¡ÂºÂ·c bÃ¡ÂºÂ¡n khÃƒÂ´ng cÃƒÂ³ quyÃ¡Â»Ân xem'
        });
      }

      // Get sessions for this payroll period
      const startDate = `${payroll.period_year}-${String(payroll.period_month).padStart(2, '0')}-01`;
      const endDate = new Date(payroll.period_year, payroll.period_month, 0).toISOString().split('T')[0];

      const { data: sessions, error: sessionsError } = await supabase
        .from('sessions')
        .select(`
          id, session_date, start_time, end_time, duration_hours, teacher_rate, status, is_locked,
          classes (id, name, code)
        `)
        .eq('teacher_id', teacherId)
        .eq('status', 'completed')
        .gte('session_date', startDate)
        .lte('session_date', endDate)
        .order('session_date', { ascending: true });

      if (sessionsError) throw sessionsError;

      // Fetch teacher info for payslip
      const { data: teacherInfo } = await supabase
        .from('users')
        .select('full_name, email')
        .eq('id', teacherId)
        .single();

      // Fetch compensation for hourly rate
      const { data: compensation } = await supabase
        .from('teacher_compensation')
        .select('hourly_rate, pay_scheme, fixed_monthly_salary')
        .eq('teacher_id', teacherId)
        .eq('is_active', true)
        .single();

      res.json({
        success: true,
        data: {
          ...payroll,
          sessions: sessions || [],
          teacher: {
            full_name: teacherInfo?.full_name || '',
            email: teacherInfo?.email || '',
            hourly_rate: compensation?.hourly_rate || 0,
          }
        }
      });
    } catch (error) {
      console.error('Ã¢ÂÅ’ Error fetching teacher payroll detail:', error);
      next(error);
    }
  }
);

