/**
 * GET /api/admin/holidays
 * Get list of holidays with optional date range filter
 * Query: ?year=2026&month=2&from=2026-01-01&to=2026-12-31
 * Ã°Å¸â€â€™ SUPER_ADMIN, CENTER_MANAGER
 */
app.get('/api/admin/holidays',
  requireAuth,
  requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']),
  async (req, res, next) => {
    try {
      const { year, month, from, to } = req.query;
      console.log(`Ã°Å¸Å½â€ž Admin ${req.user.email} fetching holidays`);

      let query = supabase
        .from('holidays')
        .select(`
          id, name, date, description, is_recurring, created_at, updated_at,
          creator:users!holidays_created_by_fkey (id, full_name, email)
        `)
        .order('date', { ascending: true });

      // Apply date filters
      if (year && month) {
        const startDate = `${year}-${String(month).padStart(2, '0')}-01`;
        const lastDay = new Date(parseInt(year), parseInt(month), 0).getDate();
        const endDate = `${year}-${String(month).padStart(2, '0')}-${lastDay}`;
        query = query.gte('date', startDate).lte('date', endDate);
      } else if (year) {
        query = query.gte('date', `${year}-01-01`).lte('date', `${year}-12-31`);
      } else if (from && to) {
        query = query.gte('date', from).lte('date', to);
      }

      const { data, error } = await query;
      if (error) throw error;

      res.json({
        success: true,
        data: data || []
      });
    } catch (error) {
      console.error('Ã¢ÂÅ’ Error fetching holidays:', error);
      next(error);
    }
  }
);

