    if (search) {
      query = query.or(`certificate_number.ilike.%${search}%,student_name.ilike.%${search}%,course_name.ilike.%${search}%`);
    }

    const offset = (page - 1) * limit;
    query = query.range(offset, offset + parseInt(limit) - 1);

