// LÃ¡ÂºÂ¥y danh sÃƒÂ¡ch hÃ¡Â»Âc viÃƒÂªn Ã„â€˜Ã¡Â»Â§ Ã„â€˜iÃ¡Â»Âu kiÃ¡Â»â€¡n cÃ¡ÂºÂ¥p chÃ¡Â»Â©ng chÃ¡Â»â€°
app.get('/api/admin/certificates/eligible-students', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { centerId, classId, certificateTypeId: certTypeIdParam, type_id } = req.query;
    const certificateTypeId = certTypeIdParam || type_id;
    const { effectiveCenterId, error: permError } = getEffectiveCenterId(req.user, centerId);
    if (permError) {
      return res.status(403).json({ success: false, message: permError });
    }

    // LÃ¡ÂºÂ¥y cÃƒÂ¡c enrollment Ã„â€˜ang hÃ¡Â»Âc hoÃ¡ÂºÂ·c Ã„â€˜ÃƒÂ£ hoÃƒÂ n thÃƒÂ nh
    let query = supabase
      .from('enrollments')
      .select(`
        id,
        student_id,
        class_id,
        status,
        student:users!enrollments_student_id_fkey (id, full_name, email),
        class:classes (
          id, code, name, status, end_date,
          course:courses (id, code, title),
          center:centers (id, name)
        )
      `)
      .in('status', ['active', 'completed']);

    if (classId) {
      query = query.eq('class_id', classId);
    }

    const { data: completedEnrollments, error: enrollError } = await query;
    if (enrollError) throw enrollError;

    // Filter by center
    let enrollments = (completedEnrollments || []).filter(e => {
      return !effectiveCenterId || e.class?.center?.id === effectiveCenterId;
    });

    // Filter by linked_course_ids if certificate type specified
    if (certificateTypeId) {
      const { data: certTypeData } = await supabase
        .from('certificate_types')
        .select('linked_course_ids')
        .eq('id', certificateTypeId)
        .single();

      const linkedCourseIds = certTypeData?.linked_course_ids || [];
      if (linkedCourseIds.length > 0) {
        enrollments = enrollments.filter(e =>
          linkedCourseIds.includes(e.class?.course?.id)
        );
      }
    }

    // LÃ¡ÂºÂ¥y danh sÃƒÂ¡ch Ã„â€˜ÃƒÂ£ cÃƒÂ³ chÃ¡Â»Â©ng chÃ¡Â»â€°
    const { data: existingCerts } = await supabase
      .from('certificates')
      .select('student_id, class_id, certificate_type_id')
      .in('status', ['issued']);

    const existingCertKeys = new Set(
      (existingCerts || []).map(c => `${c.student_id}_${c.class_id}_${c.certificate_type_id || ''}`)
    );

    // Check eligibility using DB function for each student
    const eligibleStudents = [];
    for (const enrollment of enrollments) {
      // Skip if already has certificate for this type+class combo
      if (certificateTypeId) {
        const key = `${enrollment.student_id}_${enrollment.class?.id}_${certificateTypeId}`;
        if (existingCertKeys.has(key)) continue;
      }

      // Check eligibility via service function (uses DB function)
      if (certificateTypeId) {
        const eligibility = await checkCertificateEligibility(
          supabase, enrollment.student_id, enrollment.class_id, certificateTypeId
        );
        eligibleStudents.push({
          id: enrollment.id,
          student_id: enrollment.student_id,
          class_id: enrollment.class_id,
          status: enrollment.status,
          student_name: enrollment.student?.full_name || '',
          full_name: enrollment.student?.full_name || '',
          email: enrollment.student?.email || '',
          class_name: enrollment.class?.name || '',
          class_code: enrollment.class?.code || '',
          course_name: enrollment.class?.course?.title || '',
          is_eligible: eligibility.eligible,
          eligible: eligibility.eligible,
          attendance_rate: eligibility.attendance_rate,
          average_grade: eligibility.average_grade,
          min_attendance_required: eligibility.min_attendance_required,
          min_grade_required: eligibility.min_grade_required,
          reasons: eligibility.reasons || []
        });
      } else {
        // No cert type specified Ã¢â‚¬â€ return all without eligibility details
        const key = `${enrollment.student_id}_${enrollment.class?.id}`;
        const hasAnyCert = (existingCerts || []).some(c =>
          `${c.student_id}_${c.class_id}` === key
        );
        if (!hasAnyCert) {
          eligibleStudents.push({
            id: enrollment.id,
            student_id: enrollment.student_id,
            class_id: enrollment.class_id,
            status: enrollment.status,
            student_name: enrollment.student?.full_name || '',
            full_name: enrollment.student?.full_name || '',
            email: enrollment.student?.email || '',
            class_name: enrollment.class?.name || '',
            class_code: enrollment.class?.code || '',
            course_name: enrollment.class?.course?.title || '',
            is_eligible: null,
            eligible: null,
            attendance_rate: null,
            average_grade: null,
            reasons: []
          });
        }
      }
    }
    // Dedup by student_id Ã¢â‚¬â€ keep best enrollment per student (eligible first, then first found)
    const seenStudents = new Map();
    for (const student of eligibleStudents) {
      const existing = seenStudents.get(student.student_id);
      if (!existing || (student.is_eligible && !existing.is_eligible)) {
        seenStudents.set(student.student_id, student);
      }
    }
    const dedupedStudents = Array.from(seenStudents.values());

    res.json({
      success: true,
      data: dedupedStudents
    });
  } catch (error) {
    console.error('Error fetching eligible students:', error);
    next(error);
  }
});

// CÃ¡ÂºÂ¥p chÃ¡Â»Â©ng chÃ¡Â»â€° nÃ¡Â»â„¢i bÃ¡Â»â„¢ (issued ngay lÃ¡ÂºÂ­p tÃ¡Â»Â©c khi admin xÃƒÂ¡c nhÃ¡ÂºÂ­n qua wizard)
app.post('/api/admin/certificates/request-approval', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { certificate_type_id, students, options = {} } = req.body;
    console.log('=== ISSUE CERTIFICATE REQUEST ===');
    console.log('User:', req.user?.email, 'Role:', req.user?.roleCode, 'CenterId:', req.user?.centerId);
    console.log('CertTypeId:', certificate_type_id, 'Students count:', students?.length);
    const { effectiveCenterId, error: permError } = getEffectiveCenterId(req.user, req.body.center_id);
    console.log('EffectiveCenterId:', effectiveCenterId, 'PermError:', permError);
    if (permError) {
      return res.status(403).json({ success: false, message: permError });
    }

    if (!certificate_type_id || !students || !Array.isArray(students) || students.length === 0) {
      return res.status(400).json({ success: false, message: 'ThiÃ¡ÂºÂ¿u thÃƒÂ´ng tin bÃ¡ÂºÂ¯t buÃ¡Â»â„¢c' });
    }

    // LÃ¡ÂºÂ¥y thÃƒÂ´ng tin certificate type
    const { data: certType, error: typeError } = await supabase
      .from('certificate_types')
      .select('*')
      .eq('id', certificate_type_id)
      .single();

    if (typeError || !certType) {
      return res.status(404).json({ success: false, message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y loÃ¡ÂºÂ¡i chÃ¡Â»Â©ng chÃ¡Â»â€°' });
    }

    const results = { success: [], failed: [] };

    for (const student of students) {
      try {
        const { student_id, scores, override_reason, class_id, course_name } = student;

        // LÃ¡ÂºÂ¥y thÃƒÂ´ng tin hÃ¡Â»Âc viÃƒÂªn
        const { data: profile } = await supabase
          .from('users')
          .select('full_name')
          .eq('id', student_id)
          .single();

        const studentName = profile?.full_name || 'Unknown';

        // TÃ¡ÂºÂ¡o certificate number
        const { data: certNumber } = await supabase.rpc('generate_certificate_number_v2', {
          p_type_code: certType.code || 'INT',
          p_center_code: 'SM'
        });

        // TÃƒÂ­nh ngÃƒÂ y hÃ¡ÂºÂ¿t hÃ¡ÂºÂ¡n nÃ¡ÂºÂ¿u cÃƒÂ³ validity_months
        let expiresAt = null;
        if (certType.validity_months) {
          const expiry = new Date();
          expiry.setMonth(expiry.getMonth() + certType.validity_months);
          expiresAt = expiry.toISOString().split('T')[0];
        }

        // XÃƒÂ¡c Ã„â€˜Ã¡Â»â€¹nh grade tÃ¡Â»Â« scores
        const grade = scores?.grade || scores?.overall || null;

        const insertData = {
          certificate_number: certNumber || `SM-${Date.now()}`,
          certificate_type_id,
          student_id,
          student_name: studentName,
          course_name: course_name || certType.name,
          class_id: class_id || null,
          completion_date: new Date().toISOString().split('T')[0],
          grade,
          scores: scores || {},
          center_id: effectiveCenterId,
          status: 'issued',
          issued_by: req.user.id,
          issued_at: new Date().toISOString(),
          expires_at: expiresAt,
        };

        const { data: cert, error: insertError } = await supabase
          .from('certificates')
          .insert(insertData)
          .select('*, certificate_type:certificate_types(id, name, code, category)')
          .single();

        if (insertError) {
          console.error('Insert cert error:', insertError);
          results.failed.push({ student_id, student_name: studentName, error: insertError.message });
        } else {
          results.success.push(cert);
        }
      } catch (err) {
        console.error('Student cert error:', err);
        results.failed.push({ student_id: student.student_id, error: err.message });
      }
    }

    res.json({
      success: true,
      message: `Ã„ÂÃƒÂ£ cÃ¡ÂºÂ¥p ${results.success.length} chÃ¡Â»Â©ng chÃ¡Â»â€° thÃƒÂ nh cÃƒÂ´ng`,
      data: results
    });
  } catch (error) {
    console.error('Request approval error:', error);
    next(error);
  }
});

// CÃ¡ÂºÂ¥p chÃ¡Â»Â©ng chÃ¡Â»â€° hÃƒÂ ng loÃ¡ÂºÂ¡t cho mÃ¡Â»â„¢t lÃ¡Â»â€ºp
app.post('/api/admin/certificates/bulk', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { certificates, class_id, student_ids, grade, completion_date } = req.body;

    console.log('=== BULK CERTIFICATE REQUEST ===');
    console.log('User:', req.user?.email, 'Center ID:', req.user?.centerId, 'Role:', req.user?.roleCode);
    console.log('Certificates count:', certificates?.length);
    console.log('First cert:', certificates?.[0]);

    if (!req.user?.centerId) {
      return res.status(400).json({
        success: false,
        message: 'User khÃƒÂ´ng cÃƒÂ³ center_id, khÃƒÂ´ng thÃ¡Â»Æ’ cÃ¡ÂºÂ¥p chÃ¡Â»Â©ng chÃ¡Â»â€°'
      });
    }

    // HÃ¡Â»â€” trÃ¡Â»Â£ cÃ¡ÂºÂ£ format mÃ¡Â»â€ºi (certificates array) vÃƒÂ  format cÃ…Â© (class_id + student_ids)
    if (certificates && Array.isArray(certificates) && certificates.length > 0) {
      // NEW FORMAT: CÃ¡ÂºÂ¥p nhiÃ¡Â»Âu chÃ¡Â»Â©ng chÃ¡Â»â€° vÃ¡Â»â€ºi thÃƒÂ´ng tin chi tiÃ¡ÂºÂ¿t tÃ¡Â»Â«ng ngÃ†Â°Ã¡Â»Âi
      const results = { success: [], failed: [] };

      for (const cert of certificates) {
        try {
          // Validate required fields
          if (!cert.certificate_type_id || !cert.student_id) {
            results.failed.push({
              student_id: cert.student_id,
              reason: 'ThiÃ¡ÂºÂ¿u certificate_type_id hoÃ¡ÂºÂ·c student_id'
            });
            continue;
          }

          // Generate certificate number
          const { data: certNumber } = await supabase.rpc('generate_certificate_number');
          const generatedNumber = certNumber || `SM-${new Date().getFullYear()}${String(new Date().getMonth() + 1).padStart(2, '0')}-${Math.random().toString(36).substring(2, 6).toUpperCase()}`;

          // Calculate expiry date based on certificate type
          let expiryDate = null;
          if (cert.certificate_type_id) {
            try {
              const { data: certType } = await supabase
                .from('certificate_types')
                .select('validity_months')
                .eq('id', cert.certificate_type_id)
                .single();

              if (certType?.validity_months) {
                const expiry = new Date();
                expiry.setMonth(expiry.getMonth() + certType.validity_months);
                expiryDate = expiry.toISOString().split('T')[0];
              }
            } catch (e) {
              // Column may not exist, skip expiry date calculation
              console.log('Skipping expiry date calculation:', e.message);
            }
          }

          const insertData = {
            certificate_number: generatedNumber,
            certificate_type_id: cert.certificate_type_id,
            student_id: cert.student_id,
            student_name: cert.student_name,
            course_name: cert.course_name,
            completion_date: cert.completion_date || new Date().toISOString().split('T')[0],
            grade: cert.grade,
            scores: cert.scores || {},
            external_id: cert.external_id,
            exam_date: cert.exam_date,
            expires_at: expiryDate,
            center_id: req.user.centerId,
            status: 'issued',
            issued_by: req.user.id,
            issued_at: new Date().toISOString()
          };

          const { data, error } = await supabase
            .from('certificates')
            .insert(insertData)
            .select(`
              *,
              certificate_type:certificate_types (id, name, code, category)
            `)
            .single();

          if (error) {
            console.error('Error inserting certificate:', error);
            console.error('Insert data was:', insertData);
            results.failed.push({ student_id: cert.student_id, reason: error.message });
          } else {
            console.log('Successfully inserted certificate:', data.certificate_number);
            results.success.push(data);
          }
        } catch (err) {
          console.error('Error processing certificate:', err);
          results.failed.push({ student_id: cert.student_id, reason: err.message });
        }
      }

      console.log('=== BULK RESULT ===');
      console.log('Success:', results.success.length);
      console.log('Failed:', results.failed.length);
      if (results.failed.length > 0) {
        console.log('Failed details:', results.failed);
      }

      return res.status(201).json({
        success: true,
        message: `Ã„ÂÃƒÂ£ cÃ¡ÂºÂ¥p ${results.success.length}/${certificates.length} chÃ¡Â»Â©ng chÃ¡Â»â€°`,
        data: results
      });
    }

    // OLD FORMAT: CÃ¡ÂºÂ¥p chÃ¡Â»Â©ng chÃ¡Â»â€° tÃ¡Â»Â« class
    if (!class_id || !student_ids || !student_ids.length) {
      return res.status(400).json({
        success: false,
        message: 'CÃ¡ÂºÂ§n cÃƒÂ³ certificates array hoÃ¡ÂºÂ·c class_id + student_ids'
      });
    }

    // LÃ¡ÂºÂ¥y thÃƒÂ´ng tin lÃ¡Â»â€ºp vÃƒÂ  khÃƒÂ³a hÃ¡Â»Âc
    const { data: classData, error: classError } = await supabase
      .from('classes')
      .select('id, name, end_date, course:courses(id, title), center:centers(id)')
      .eq('id', class_id)
      .single();

    if (classError || !classData) {
      return res.status(400).json({
        success: false,
        message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y lÃ¡Â»â€ºp hÃ¡Â»Âc'
      });
    }

    // LÃ¡ÂºÂ¥y thÃƒÂ´ng tin hÃ¡Â»Âc viÃƒÂªn
    const { data: students } = await supabase
      .from('users')
      .select('id, full_name')
      .in('id', student_ids);

    const results = { success: [], failed: [] };

    for (const studentId of student_ids) {
      try {
        const student = students?.find(s => s.id === studentId);
        if (!student) {
          results.failed.push({ student_id: studentId, reason: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y hÃ¡Â»Âc viÃƒÂªn' });
          continue;
        }

        // Generate certificate number
        const { data: certNumber } = await supabase.rpc('generate_certificate_number');

        const { data, error } = await supabase
          .from('certificates')
          .insert({
            certificate_number: certNumber || `CC-${Date.now()}-${studentId.slice(0, 4)}`,
            student_id: studentId,
            student_name: student.full_name,
            course_id: classData.course.id,
            class_id: class_id,
            course_name: classData.course.title,
            completion_date: completion_date || classData.end_date || new Date().toISOString().split('T')[0],
            grade: grade || 'pass',
            center_id: classData.center?.id || req.user.centerId,
            status: 'issued',
            issued_by: req.user.id,
            issued_at: new Date().toISOString()
          })
          .select()
          .single();

        if (error) {
          results.failed.push({ student_id: studentId, reason: error.message });
        } else {
          results.success.push(data);
        }
      } catch (err) {
        results.failed.push({ student_id: studentId, reason: err.message });
      }
    }

    res.status(201).json({
      success: true,
      message: `Ã„ÂÃƒÂ£ cÃ¡ÂºÂ¥p ${results.success.length}/${student_ids.length} chÃ¡Â»Â©ng chÃ¡Â»â€°`,
      data: results
    });
  } catch (error) {
    console.error('Error bulk issuing certificates:', error);
    next(error);
  }
});

