// ============ CERTIFICATE APPROVAL ENDPOINTS ============

const listPendingCertificateApprovals = async (req, res, next) => {
  try {
    const supabaseClient = supabase;
    const { effectiveCenterId, error: permError } = getEffectiveCenterId(req.user, req.query.center_id);
    if (permError) {
      return res.status(403).json({ success: false, error: permError });
    }

    const buildPendingCertificatesSelect = (includeTypeRelation = true) => `
        id,
        certificate_number,
        certificate_type_id,
        status,
        issued_at,
        created_at,
        student:users!certificates_student_id_fkey(id, full_name, email),
        class:classes(id, code, name, center_id),
        course:courses(id, code, title)
        ${includeTypeRelation ? ',\n        certificate_type_ref:certificate_types!certificates_certificate_type_id_fkey(id, code, name)' : ''}
      `;

    const relationStrategies = [true, false];
    let data = null;
    let error = null;

    for (const includeTypeRelation of relationStrategies) {
      let query = supabaseClient
        .from('certificates')
        .select(buildPendingCertificatesSelect(includeTypeRelation))
        .eq('status', 'pending_approval')
        .order('created_at', { ascending: false });

      if (effectiveCenterId) {
        query = query.eq('center_id', effectiveCenterId);
      }

      const result = await query;
      data = result.data;
      error = result.error;

      if (!error) {
        break;
      }
    }

    if (error) throw error;

    res.json({ success: true, data: data || [] });
  } catch (error) {
    console.error('Error fetching pending certificate approvals:', error);
    next(error);
  }
};

// GET /api/admin/certificates/pending-approvals - List pending certificate approvals
app.get('/api/admin/certificates/pending-approvals', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), listPendingCertificateApprovals);

// Backward-compatible alias for older frontend bundles
app.get('/api/admin/cert_pending_approvals', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), listPendingCertificateApprovals);

// PUT /api/admin/certificates/:id/approve
app.put('/api/admin/certificates/:id/approve', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { id: rawId } = req.params;
    const id = typeof rawId === 'string' && rawId.startsWith('cert_') ? rawId.slice(5) : rawId;
    const supabaseClient = req.supabase || supabase;

    const { data: cert, error: certError } = await supabaseClient
      .from('certificates')
      .update({ status: 'issued' })
      .eq('id', id)
      .eq('status', 'pending_approval')
      .select()
      .maybeSingle();

    if (certError) {
      throw certError;
    }

    if (!cert) {
      return res.status(404).json({ success: false, error: 'Certificate not found or already processed' });
    }

    await supabaseClient
      .from('certificate_approvals')
      .update({
        status: 'approved',
        approved_by: req.user.id,
        approved_at: new Date().toISOString()
      })
      .contains('certificate_ids', [id])
      .eq('status', 'pending');

    AuditLogService.log({
      ...getAuditContext(req),
      action: 'CERTIFICATE_APPROVED',
      entityType: 'certificate',
      entityId: id,
      status: 'SUCCESS'
    });

    res.json({ success: true, data: cert });
  } catch (error) {
    console.error('Error approving certificate:', error);
    next(error);
  }
});

// PUT /api/admin/certificates/:id/reject
app.put('/api/admin/certificates/:id/reject', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { id: rawId } = req.params;
    const id = typeof rawId === 'string' && rawId.startsWith('cert_') ? rawId.slice(5) : rawId;
    const { reason } = req.body;
    const supabaseClient = req.supabase || supabase;

    if (!reason) {
      return res.status(400).json({ success: false, error: 'Rejection reason is required' });
    }

    const { data: cert, error: certError } = await supabaseClient
      .from('certificates')
      .update({ status: 'revoked' })
      .eq('id', id)
      .eq('status', 'pending_approval')
      .select()
      .maybeSingle();

    if (certError) {
      throw certError;
    }

    if (!cert) {
      return res.status(404).json({ success: false, error: 'Certificate not found or already processed' });
    }

    await supabaseClient
      .from('certificate_approvals')
      .update({
        status: 'rejected',
        rejected_by: req.user.id,
        rejected_at: new Date().toISOString(),
        rejection_reason: reason
      })
      .contains('certificate_ids', [id])
      .eq('status', 'pending');

    AuditLogService.log({
      ...getAuditContext(req),
      action: 'CERTIFICATE_REJECTED',
      entityType: 'certificate',
      entityId: id,
      status: 'SUCCESS',
      metadata: { reason }
    });

    res.json({ success: true, data: cert });
  } catch (error) {
    console.error('Error rejecting certificate:', error);
    next(error);
  }
});

// ============ UNIFIED PENDING APPROVALS ============

// GET /api/admin/pending-approvals - Aggregate pending counts from all sources
app.get('/api/admin/pending-approvals', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const supabaseClient = req.supabase || supabase;
    const { effectiveCenterId, error: permError } = getEffectiveCenterId(req.user, req.query.center_id);
    if (permError) {
      return res.status(403).json({ success: false, error: permError });
    }

    const buildQuery = (table, statusCol, statusVal) => {
      let q = supabaseClient.from(table).select('id', { count: 'exact', head: true });
      if (Array.isArray(statusVal)) {
        q = q.in(statusCol, statusVal);
      } else {
        q = q.eq(statusCol, statusVal);
      }
      if (effectiveCenterId) {
        q = q.eq('center_id', effectiveCenterId);
      }
      return q;
    };

    const [enrollments, certificates, payments, payroll, disputes, leaves] = await Promise.all([
      buildQuery('enrollment_requests', 'status', 'pending'),
      buildQuery('certificates', 'status', 'pending_approval'),
      buildQuery('payments', 'verification_status', 'pending'),
      buildQuery('payroll', 'status', 'pending'),
      buildQuery('payroll_disputes', 'status', ['pending', 'reviewing']),
      buildQuery('leave_requests', 'status', 'pending')
    ]);

    const counts = {
      enrollments: enrollments.count || 0,
      certificates: certificates.count || 0,
      payments: payments.count || 0,
      payroll: payroll.count || 0,
      disputes: disputes.count || 0,
      leaves: leaves.count || 0
    };
    counts.total = Object.values(counts).reduce((a, b) => a + b, 0);

    res.json({ success: true, data: counts });
  } catch (error) {
    console.error('Error fetching pending approvals:', error);
    next(error);
  }
});

// ============================================================
// PUBLIC CERTIFICATE VERIFICATION API - XÃƒÂ¡c thÃ¡Â»Â±c chÃ¡Â»Â©ng chÃ¡Â»â€° cÃƒÂ´ng khai
// ============================================================

/**
 * @api {GET} /api/public/verify-certificate/:certificateNumber
 * @description XÃƒÂ¡c thÃ¡Â»Â±c chÃ¡Â»Â©ng chÃ¡Â»â€° theo mÃƒÂ£ sÃ¡Â»â€˜ - KHÃƒâ€NG CÃ¡ÂºÂ¦N Ã„ÂÃ„â€šNG NHÃ¡ÂºÂ¬P
 */
app.get('/api/public/verify-certificate/:certificateNumber', async (req, res, next) => {
  try {
    // Decode URL-encoded certificate number and trim whitespace
    const certificateNumber = decodeURIComponent(req.params.certificateNumber).trim();

    console.log('=== VERIFY CERTIFICATE ===');
    console.log('Certificate number:', certificateNumber);

    if (!certificateNumber || certificateNumber.length < 3) {
      return res.status(400).json({
        success: false,
        message: 'MÃƒÂ£ chÃ¡Â»Â©ng chÃ¡Â»â€° khÃƒÂ´ng hÃ¡Â»Â£p lÃ¡Â»â€¡',
        code: 'INVALID_FORMAT'
      });
    }

    // TÃƒÂ¬m chÃ¡Â»Â©ng chÃ¡Â»â€° vÃ¡Â»â€ºi mÃƒÂ£ sÃ¡Â»â€˜ (case-insensitive)
    const { data: certificate, error } = await supabase
      .from('certificates')
      .select(`
        id,
        certificate_number,
        student_name,
        course_name,
        grade,
        scores,
        completion_date,
        issued_at,
        status,
        certificate_type:certificate_types (
          id,
          name,
          code,
          category,
          is_external,
          is_internal,
          provider
        ),
        center:centers (
          id,
          name,
          address
        )
      `)
      .ilike('certificate_number', certificateNumber)
      .single();

    if (error || !certificate) {
      console.log('Certificate not found:', certificateNumber, error);
      return res.status(404).json({
        success: false,
        message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y chÃ¡Â»Â©ng chÃ¡Â»â€° vÃ¡Â»â€ºi mÃƒÂ£ sÃ¡Â»â€˜ nÃƒÂ y',
        code: 'CERTIFICATE_NOT_FOUND',
        searched_code: certificateNumber
      });
    }

    // KhÃƒÂ´ng trÃ¡ÂºÂ£ vÃ¡Â»Â student_id hoÃ¡ÂºÂ·c thÃƒÂ´ng tin nhÃ¡ÂºÂ¡y cÃ¡ÂºÂ£m
    const publicData = {
      certificate_number: certificate.certificate_number,
      student_name: certificate.student_name,
      course_name: certificate.course_name,
      grade: certificate.grade,
      scores: certificate.scores,
      completion_date: certificate.completion_date,
      issued_at: certificate.issued_at,
      expiry_date: certificate.expiry_date,
      status: certificate.status,
      certificate_type: certificate.certificate_type,
      center: certificate.center ? {
        name: certificate.center.name,
        address: certificate.center.address
      } : null
    };

    // KiÃ¡Â»Æ’m tra trÃ¡ÂºÂ¡ng thÃƒÂ¡i
    let verificationStatus = 'valid';
    if (certificate.status === 'revoked') {
      verificationStatus = 'revoked';
    } else if (certificate.expiry_date && new Date(certificate.expiry_date) < new Date()) {
      verificationStatus = 'expired';
    }

    // Log verification attempt
    console.log(`[VERIFY] Certificate ${certificateNumber} verified - Status: ${verificationStatus}`);

    res.json({
      success: true,
      data: publicData,
      verification_status: verificationStatus,
      verified_at: new Date().toISOString()
    });

  } catch (error) {
    console.error('Error verifying certificate:', error);
    res.status(500).json({
      success: false,
      message: 'LÃ¡Â»â€”i hÃ¡Â»â€¡ thÃ¡Â»â€˜ng khi xÃƒÂ¡c thÃ¡Â»Â±c chÃ¡Â»Â©ng chÃ¡Â»â€°. Vui lÃƒÂ²ng thÃ¡Â»Â­ lÃ¡ÂºÂ¡i sau.',
      code: 'SERVER_ERROR'
    });
  }
});

