// ========================================
// Ã°Å¸â€Â¥ BATCH ENROLLMENT - Ghi danh nhiÃ¡Â»Âu hÃ¡Â»Âc viÃƒÂªn cÃƒÂ¹ng lÃƒÂºc
// ========================================
app.post('/api/admin/enrollments/batch', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { student_ids, class_id, tuition_fee } = req.body;

    // Validation
    if (!class_id || !student_ids || !Array.isArray(student_ids) || student_ids.length === 0) {
      return res.status(400).json({
        success: false,
        message: 'HÃ¡Â»Âc viÃƒÂªn vÃƒÂ  lÃ¡Â»â€ºp hÃ¡Â»Âc lÃƒÂ  bÃ¡ÂºÂ¯t buÃ¡Â»â„¢c'
      });
    }

    // Validate student_ids length (max 50 at once)
    if (student_ids.length > 50) {
      return res.status(400).json({
        success: false,
        message: 'TÃ¡Â»â€˜i Ã„â€˜a 50 hÃ¡Â»Âc viÃƒÂªn mÃ¡Â»â€”i lÃ¡ÂºÂ§n ghi danh'
      });
    }

    // Check class capacity
    const { data: classData, error: classError } = await supabase
      .from('classes')
      .select('id, max_students, code, name, courses(price)')
      .eq('id', class_id)
      .single();

    if (classError || !classData) {
      return res.status(404).json({
        success: false,
        message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y lÃ¡Â»â€ºp hÃ¡Â»Âc'
      });
    }

    const { count: currentCount } = await supabase
      .from('enrollments')
      .select('id', { count: 'exact' })
      .eq('class_id', class_id)
      .neq('status', 'dropped');

    const availableSlots = classData.max_students - currentCount;
    if (student_ids.length > availableSlots) {
      return res.status(400).json({
        success: false,
        message: `LÃ¡Â»â€ºp hÃ¡Â»Âc chÃ¡Â»â€° cÃƒÂ²n ${availableSlots} chÃ¡Â»â€” trÃ¡Â»â€˜ng`
      });
    }

    // Check for existing enrollments - separate active from dropped
    const { data: existingEnrollments } = await supabase
      .from('enrollments')
      .select('id, student_id, status')
      .eq('class_id', class_id)
      .in('student_id', student_ids);

    const activeIds = new Set((existingEnrollments || []).filter(e => e.status === 'active').map(e => e.student_id));
    const droppedEnrollments = (existingEnrollments || []).filter(e => e.status === 'dropped');
    const droppedIds = new Set(droppedEnrollments.map(e => e.student_id));
    const newStudentIds = student_ids.filter(id => !activeIds.has(id) && !droppedIds.has(id));
    const reactivateIds = student_ids.filter(id => droppedIds.has(id) && !activeIds.has(id));

    console.log('[BatchEnroll] Active (skip):', [...activeIds]);
    console.log('[BatchEnroll] Dropped (reactivate):', reactivateIds);
    console.log('[BatchEnroll] New (insert):', newStudentIds);

    if (newStudentIds.length === 0 && reactivateIds.length === 0) {
      return res.status(400).json({
        success: false,
        message: 'TÃ¡ÂºÂ¥t cÃ¡ÂºÂ£ hÃ¡Â»Âc viÃƒÂªn Ã„â€˜ÃƒÂ£ Ã„â€˜Ã†Â°Ã¡Â»Â£c ghi danh vÃƒÂ o lÃ¡Â»â€ºp nÃƒÂ y'
      });
    }

    // Reactivate dropped enrollments
    let reactivatedData = [];
    if (reactivateIds.length > 0) {
      const reactivateEnrollmentIds = droppedEnrollments
        .filter(e => reactivateIds.includes(e.student_id))
        .map(e => e.id);
      const { data: reactivated, error: reactivateError } = await supabase
        .from('enrollments')
        .update({ status: 'active', enrolled_at: new Date().toISOString() })
        .in('id', reactivateEnrollmentIds)
        .select();
      if (reactivateError) throw reactivateError;
      reactivatedData = reactivated || [];
    }

    // Batch insert new students
    let insertedData = [];
    if (newStudentIds.length > 0) {
      const enrollments = newStudentIds.map(student_id => ({
        student_id,
        class_id,
        tuition_fee: tuition_fee || 0,
        discount_amount: 0,
        paid_amount: 0,
        status: 'active',
        enrolled_at: new Date().toISOString()
      }));

      const { data, error } = await supabase
        .from('enrollments')
        .insert(enrollments)
        .select();

      if (error) throw error;
      insertedData = data || [];
    }

    // Combine all enrolled (new + reactivated)
    const allEnrolled = [...insertedData, ...reactivatedData];

    // Create draft invoices for all enrolled
    const invoiceResults = [];
    const invoiceErrors = [];

    for (const enrollment of allEnrolled) {
      try {
        const invoiceResult = await createDraftInvoice(supabase, {
          student_id: enrollment.student_id,
          enrollment_id: enrollment.id,
          class_id: enrollment.class_id,
          class_name: classData.name,
          tuition_fee: enrollment.tuition_fee || classData.courses?.price || 0,
          discount_amount: 0,
          paid_amount: 0,
          description: `HÃ¡Â»Âc phÃƒÂ­ lÃ¡Â»â€ºp ${classData.name}`,
          created_by: req.user?.id
        });

        if (invoiceResult.data) {
          invoiceResults.push(invoiceResult.data);
        } else if (invoiceResult.error) {
          invoiceErrors.push({ student_id: enrollment.student_id, error: invoiceResult.error });
        }
      } catch (invoiceErr) {
        console.error(`Failed to create invoice for enrollment ${enrollment.id}:`, invoiceErr);
        invoiceErrors.push({ student_id: enrollment.student_id, error: invoiceErr.message });
      }
    }

    console.log(`Ã¢Å“â€¦ Batch enrollment: ${insertedData.length} new, ${reactivatedData.length} reactivated, ${invoiceResults.length} invoices`);

    res.status(201).json({
      success: true,
      data: {
        enrolled: allEnrolled.length,
        new_enrolled: insertedData.length,
        reactivated: reactivatedData.length,
        skipped: activeIds.size,
        total: student_ids.length,
        invoices_created: invoiceResults.length,
        invoice_errors: invoiceErrors.length > 0 ? invoiceErrors : undefined
      },
      message: `Đã ghi danh ${allEnrolled.length} học viên và tạo ${invoiceResults.length} hóa đơn nháp`
    });
  } catch (error) {
    console.error('Error batch enrollment:', error);
    next(error);
  }
});

