/**
 * PUT /api/admin/students/:id/transfer
 * ChuyÃ¡Â»Æ’n hÃ¡Â»Âc viÃƒÂªn sang chi nhÃƒÂ¡nh khÃƒÂ¡c
 * - GiÃ¡Â»Â¯ nguyÃƒÂªn lÃ¡Â»â€¹ch sÃ¡Â»Â­ hÃ¡Â»Âc tÃ¡ÂºÂ­p (grades, attendance)
 * - CÃ¡ÂºÂ­p nhÃ¡ÂºÂ­t center_id cÃ¡Â»Â§a student
 * - TÃƒÂ¹y chÃ¡Â»Ân: chuyÃ¡Â»Æ’n enrollments Ã„â€˜ang active hoÃ¡ÂºÂ·c close
 * - Ghi log audit trail
 */
app.put('/api/admin/students/:id/transfer', requireAuth, requireRole(['SUPER_ADMIN']), async (req, res, next) => {
  try {
    const { id } = req.params;
    const {
      target_center_id,
      transfer_enrollments = false, // true = chuyÃ¡Â»Æ’n cÃ¡ÂºÂ£ enrollment, false = close enrollment cÃ…Â©
      notes = ''
    } = req.body;

    console.log(`Ã°Å¸â€â€ž Student transfer initiated by ${req.user.email}: ${id} -> ${target_center_id}`);

    // Validate required fields
    if (!target_center_id) {
      return res.status(400).json({
        success: false,
        message: 'Vui lÃƒÂ²ng chÃ¡Â»Ân chi nhÃƒÂ¡nh Ã„â€˜ÃƒÂ­ch'
      });
    }

    // Get student info
    const { data: student, error: studentError } = await supabase
      .from('users')
      .select(`
        id, full_name, email, phone, center_id,
        roles!users_role_id_fkey (code)
      `)
      .eq('id', id)
      .single();

    if (studentError || !student) {
      return res.status(404).json({
        success: false,
        message: 'KhÃƒÂ´ng tÃƒÂ¬m thÃ¡ÂºÂ¥y hÃ¡Â»Âc viÃƒÂªn'
      });
    }

    // Verify it's a student
    if (student.roles?.code !== 'STUDENT') {
      return res.status(400).json({
        success: false,
        message: 'ChÃ¡Â»â€° cÃƒÂ³ thÃ¡Â»Æ’ chuyÃ¡Â»Æ’n hÃ¡Â»Âc viÃƒÂªn (STUDENT role)'
      });
    }

    const sourceCenterId = student.center_id;

    // Check if already in target center
    if (sourceCenterId === target_center_id) {
      return res.status(400).json({
        success: false,
        message: 'HÃ¡Â»Âc viÃƒÂªn Ã„â€˜ÃƒÂ£ thuÃ¡Â»â„¢c chi nhÃƒÂ¡nh nÃƒÂ y'
      });
    }

    // Validate target center exists
    const { data: targetCenter, error: centerError } = await supabase
      .from('centers')
      .select('id, name, code')
      .eq('id', target_center_id)
      .single();

    if (centerError || !targetCenter) {
      return res.status(400).json({
        success: false,
        message: 'Chi nhÃƒÂ¡nh Ã„â€˜ÃƒÂ­ch khÃƒÂ´ng tÃ¡Â»â€œn tÃ¡ÂºÂ¡i'
      });
    }

    // Get source center name for logging
    let sourceCenterName = 'ChÃ†Â°a cÃƒÂ³';
    if (sourceCenterId) {
      const { data: sourceCenter } = await supabase
        .from('centers')
        .select('name')
        .eq('id', sourceCenterId)
        .single();
      sourceCenterName = sourceCenter?.name || 'Unknown';
    }

    // Get active enrollments
    const { data: activeEnrollments } = await supabase
      .from('enrollments')
      .select(`
        id, class_id, status, tuition_fee, paid_amount,
        classes!enrollments_class_id_fkey (id, name, course_id, center_id)
      `)
      .eq('student_id', id)
      .in('status', ['active', 'pending']);

    // Start transaction-like operations
    const transferResults = {
      studentUpdated: false,
      enrollmentsProcessed: 0,
      enrollmentsClosed: 0,
      errors: []
    };

    // 1. Update student's center_id
    const { error: updateError } = await supabase
      .from('users')
      .update({
        center_id: target_center_id,
        updated_at: new Date().toISOString()
      })
      .eq('id', id);

    if (updateError) {
      throw updateError;
    }
    transferResults.studentUpdated = true;

    // 2. Handle enrollments
    if (activeEnrollments && activeEnrollments.length > 0) {
      for (const enrollment of activeEnrollments) {
        try {
          if (transfer_enrollments) {
            // Option A: Transfer enrollment (update notes, keep as-is)
            // Note: The enrollment stays linked to old class, but student now belongs to new center
            // Admin will need to manually enroll in new class at new center if needed
            await supabase
              .from('enrollments')
              .update({
                notes: `[TRANSFERRED] ${new Date().toISOString()} - ChuyÃ¡Â»Æ’n tÃ¡Â»Â« ${sourceCenterName} sang ${targetCenter.name}. ${notes}`,
                updated_at: new Date().toISOString()
              })
              .eq('id', enrollment.id);
            transferResults.enrollmentsProcessed++;
          } else {
            // Option B: Close old enrollments with transfer note
            await supabase
              .from('enrollments')
              .update({
                status: 'cancelled',
                notes: `[TRANSFERRED OUT] ${new Date().toISOString()} - HÃ¡Â»Âc viÃƒÂªn chuyÃ¡Â»Æ’n sang ${targetCenter.name}. ${notes}`,
                updated_at: new Date().toISOString()
              })
              .eq('id', enrollment.id);
            transferResults.enrollmentsClosed++;
          }
        } catch (enrollError) {
          transferResults.errors.push({
            enrollment_id: enrollment.id,
            error: enrollError.message
          });
        }
      }
    }

    // 3. Create audit log (try-catch as table might not exist)
    try {
      await supabase
        .from('audit_logs')
        .insert({
          action: 'STUDENT_TRANSFER',
          table_name: 'users',
          record_id: id,
          user_id: req.user.id,
          old_values: {
            center_id: sourceCenterId,
            center_name: sourceCenterName
          },
          new_values: {
            center_id: target_center_id,
            center_name: targetCenter.name
          },
          notes: notes || `ChuyÃ¡Â»Æ’n hÃ¡Â»Âc viÃƒÂªn ${student.full_name} tÃ¡Â»Â« ${sourceCenterName} sang ${targetCenter.name}`
        });
    } catch (auditError) {
      console.log('Audit log skipped (table may not exist):', auditError.message);
    }

    // 4. Create notification for student
    try {
      await supabase
        .from('notifications')
        .insert({
          user_id: id,
          title: 'ThÃƒÂ´ng bÃƒÂ¡o chuyÃ¡Â»Æ’n chi nhÃƒÂ¡nh',
          message: `BÃ¡ÂºÂ¡n Ã„â€˜ÃƒÂ£ Ã„â€˜Ã†Â°Ã¡Â»Â£c chuyÃ¡Â»Æ’n tÃ¡Â»Â« ${sourceCenterName} sang ${targetCenter.name}.`,
          type: 'system',
          is_read: false
        });
    } catch (notifError) {
      console.log('Notification skipped:', notifError.message);
    }

    console.log(`Ã¢Å“â€¦ Student ${student.full_name} transferred from ${sourceCenterName} to ${targetCenter.name}`);

    res.json({
      success: true,
      message: `Ã„ÂÃƒÂ£ chuyÃ¡Â»Æ’n hÃ¡Â»Âc viÃƒÂªn ${student.full_name} sang ${targetCenter.name}`,
      data: {
        student_id: id,
        student_name: student.full_name,
        from_center: sourceCenterName,
        to_center: targetCenter.name,
        results: transferResults
      }
    });
  } catch (error) {
    console.error('Ã¢ÂÅ’ Error transferring student:', error);
    next(error);
  }
});

