/**
 * GET /api/student/invoices
 * Get student invoices and payment history
 * Query: ?status=pending|paid|all
 * Ã°Å¸â€â€™ STUDENT only
 */
app.get('/api/student/invoices',
  requireAuth,
  requireRole(['STUDENT']),
  async (req, res, next) => {
    try {
      const studentId = req.user.id;
      const { status } = req.query;

      let query = supabase
        .from('invoices')
        .select(`
          id, invoice_code, amount, discount_amount, final_amount,
          paid_amount, status, due_date, description, created_at,
          class:classes(id, name, code, course:courses(id, title)),
          payments(id, amount, payment_method, payment_date, reference_code, notes, verification_status)
        `)
        .eq('student_id', studentId)
        .order('created_at', { ascending: false });

      const today = new Date().toISOString().split('T')[0];

      if (status && status !== 'all') {
        if (status === 'pending') {
          query = query
            .in('status', ['unpaid', 'partial'])
            .gte('due_date', today);
        } else if (status === 'overdue') {
          query = query
            .in('status', ['unpaid', 'partial'])
            .lt('due_date', today);
        } else if (status === 'unpaid') {
          query = query.in('status', ['unpaid', 'partial']);
        } else {
          query = query.eq('status', status);
        }
      }

      const { data: invoices, error } = await query;
      if (error) throw error;

      // Calculate totals
      const totalAmount = (invoices || []).reduce((sum, inv) => sum + (inv.final_amount || 0), 0);
      const totalPaid = (invoices || []).reduce((sum, inv) => sum + (inv.paid_amount || 0), 0);
      const totalRemaining = totalAmount - totalPaid;
      const overdueCount = (invoices || []).filter(i =>
        i.due_date &&
        i.due_date < today &&
        !['paid', 'cancelled', 'refunded'].includes(i.status)
      ).length;
      const unpaidCount = (invoices || []).filter(i => ['unpaid', 'partial'].includes(i.status)).length;

      console.log(`Ã°Å¸â€™Â° Student invoices loaded: ${invoices?.length || 0} invoices`);

      res.json({
        success: true,
        data: {
          invoices: invoices || [],
          summary: {
            totalInvoices: invoices?.length || 0,
            totalAmount,
            totalPaid,
            totalRemaining,
            unpaidCount,
            // Alias fields for current UI
            paidAmount: totalPaid,
            unpaidAmount: totalRemaining,
            overdueCount
          }
        }
      });
    } catch (error) {
      console.error('Ã¢ÂÅ’ Error fetching student invoices:', error);
      next(error);
    }
  }
);

