/**
 * GET /api/settings/bank-config
 * Get bank configuration for payment (Admin view)
 * Query: ?centerId=xxx (optional for SUPER_ADMIN)
 * Ã°Å¸â€â€™ ADMIN/MANAGER only
 */
app.get('/api/settings/bank-config',
  requireAuth,
  requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']),
  async (req, res, next) => {
    try {
      const { centerId } = req.query;
      const { effectiveCenterId, error } = getEffectiveCenterId(req.user, centerId);
      if (error) {
        return res.status(403).json({ success: false, message: error });
      }

      // Try to get center-specific config first
      let centerSetting = null;
      if (effectiveCenterId) {
        const { data } = await supabase
          .from('system_settings')
          .select('id, value, description, updated_at, updated_by')
          .eq('key', 'bank_config')
          .eq('center_id', effectiveCenterId)
          .single();
        centerSetting = data;
      }

      // Fallback to global config
      const { data: globalSetting } = await supabase
        .from('system_settings')
        .select('id, value, description, updated_at, updated_by')
        .eq('key', 'bank_config')
        .is('center_id', null)
        .single();

      const setting = centerSetting || globalSetting;

      if (!setting) {
        return res.json({
          success: true,
          data: null,
          message: 'ChÃ†Â°a cÃ¡ÂºÂ¥u hÃƒÂ¬nh ngÃƒÂ¢n hÃƒÂ ng thanh toÃƒÂ¡n'
        });
      }

      res.json({
        success: true,
        data: {
          ...setting.value,
          scope: centerSetting ? 'center' : 'global',
          settingId: setting.id,
          updatedAt: setting.updated_at
        }
      });
    } catch (error) {
      console.error('Ã¢ÂÅ’ Error fetching bank config:', error);
      next(error);
    }
  }
);

/**
 * PUT /api/settings/bank-config
 * Update bank configuration
 * Body: { bankId, accountNo, accountName, template?, centerId? }
 * Ã°Å¸â€â€™ ADMIN/MANAGER only
 */
app.put('/api/settings/bank-config',
  requireAuth,
  requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']),
  async (req, res, next) => {
    try {
      const { bankId, accountNo, accountName, template = 'compact2', centerId } = req.body;

      // Validate required fields
      if (!bankId || !accountNo || !accountName) {
        return res.status(400).json({
          success: false,
          message: 'Vui lÃƒÂ²ng Ã„â€˜iÃ¡Â»Ân Ã„â€˜Ã¡ÂºÂ§y Ã„â€˜Ã¡Â»Â§ thÃƒÂ´ng tin ngÃƒÂ¢n hÃƒÂ ng (bankId, accountNo, accountName)'
        });
      }

      // Permission check
      const userRole = req.user.roleCode;
      const userCenterId = req.user.centerId;

      // CENTER_MANAGER can only update their own center's config
      if (userRole === 'CENTER_MANAGER') {
        if (centerId && centerId !== userCenterId) {
          return res.status(403).json({
            success: false,
            message: 'BÃ¡ÂºÂ¡n chÃ¡Â»â€° cÃƒÂ³ thÃ¡Â»Æ’ cÃ¡ÂºÂ­p nhÃ¡ÂºÂ­t cÃ¡ÂºÂ¥u hÃƒÂ¬nh cÃ¡Â»Â§a trung tÃƒÂ¢m mÃƒÂ¬nh'
          });
        }
        // Force centerId to be the manager's center (no global update allowed)
        req.body.centerId = userCenterId;
      }

      const targetCenterId = req.body.centerId || null;
      const configValue = { bankId, accountNo, accountName, template };

      // Upsert: insert or update
      const { data: existing } = await supabase
        .from('system_settings')
        .select('id')
        .eq('key', 'bank_config')
        .is('center_id', targetCenterId)
        .single();

      let result;
      if (existing) {
        // Update existing
        const { data, error } = await supabase
          .from('system_settings')
          .update({
            value: configValue,
            updated_by: req.user.id,
            updated_at: new Date().toISOString()
          })
          .eq('id', existing.id)
          .select()
          .single();

        if (error) throw error;
        result = data;
      } else {
        // Insert new
        const { data, error } = await supabase
          .from('system_settings')
          .insert({
            key: 'bank_config',
            center_id: targetCenterId,
            value: configValue,
            description: 'CÃ¡ÂºÂ¥u hÃƒÂ¬nh ngÃƒÂ¢n hÃƒÂ ng nhÃ¡ÂºÂ­n thanh toÃƒÂ¡n VietQR',
            updated_by: req.user.id
          })
          .select()
          .single();

        if (error) throw error;
        result = data;
      }

      console.log(`Ã¢Å“â€¦ Bank config updated by ${req.user.email} - scope: ${targetCenterId ? 'center' : 'global'}`);

      res.json({
        success: true,
        message: 'Ã„ÂÃƒÂ£ cÃ¡ÂºÂ­p nhÃ¡ÂºÂ­t cÃ¡ÂºÂ¥u hÃƒÂ¬nh ngÃƒÂ¢n hÃƒÂ ng',
        data: {
          ...result.value,
          scope: targetCenterId ? 'center' : 'global',
          settingId: result.id
        }
      });
    } catch (error) {
      console.error('Ã¢ÂÅ’ Error updating bank config:', error);
      next(error);
    }
  }
);

