/**
 * GET /api/parent/child/:studentId/grades
 * Get grades for a linked child
 * Ã°Å¸â€â€™ PARENT only (must have link with can_view_academics=true)
 */
app.get('/api/parent/child/:studentId/grades',
  requireAuth,
  requireRole(['PARENT']),
  async (req, res, next) => {
    try {
      const parentId = req.user.id;
      const { studentId } = req.params;

      // Verify parent has access with academic viewing permission
      const { data: link, error: linkError } = await supabase
        .from('parent_student_links')
        .select('id, can_view_academics')
        .eq('parent_id', parentId)
        .eq('student_id', studentId)
        .eq('status', 'active')
        .single();

      if (linkError || !link) {
        return res.status(403).json({
          success: false,
          message: 'BÃ¡ÂºÂ¡n khÃƒÂ´ng cÃƒÂ³ quyÃ¡Â»Ân xem thÃƒÂ´ng tin hÃ¡Â»Âc viÃƒÂªn nÃƒÂ y'
        });
      }

      if (!link.can_view_academics) {
        return res.status(403).json({
          success: false,
          message: 'BÃ¡ÂºÂ¡n khÃƒÂ´ng cÃƒÂ³ quyÃ¡Â»Ân xem Ã„â€˜iÃ¡Â»Æ’m cÃ¡Â»Â§a hÃ¡Â»Âc viÃƒÂªn nÃƒÂ y'
        });
      }

      let query = supabase
        .from('grades')
        .select(`
          id, score, notes, created_at,
          grade_structure:grade_structures(id, name, weight, max_score),
          enrollment:enrollments!inner(
            id, student_id, class_id,
            class:classes(id, name, code, course:courses(id, title))
          )
        `)
        .eq('enrollment.student_id', studentId)
        .order('created_at', { ascending: false });

      const { classId } = req.query;
      if (classId) {
        query = query.eq('enrollment.class_id', classId);
      }

      const { data: rawGrades, error } = await query;
      if (error) throw error;

      // Group by class
      const gradesByClass = {};
      for (const grade of rawGrades || []) {
        const currentClassId = grade.enrollment?.class?.id;
        if (!currentClassId) continue;

        if (!gradesByClass[currentClassId]) {
          gradesByClass[currentClassId] = {
            classId: currentClassId,
            className: grade.enrollment.class.name,
            classCode: grade.enrollment.class.code,
            courseTitle: grade.enrollment.class.course?.title,
            grades: []
          };
        }
        gradesByClass[currentClassId].grades.push({
          id: grade.id,
          score: grade.score,
          gradeType: grade.grade_structure?.name,
          assessmentDate: grade.created_at,
          notes: grade.notes,
          weight: grade.grade_structure?.weight,
          maxScore: grade.grade_structure?.max_score
        });
      }

      console.log(`Ã°Å¸â€œÅ  Parent viewing child grades: ${rawGrades?.length || 0} grades`);

      res.json({
        success: true,
        data: {
          gradesByClass: Object.values(gradesByClass),
          totalGrades: rawGrades?.length || 0
        }
      });
    } catch (error) {
      console.error('Ã¢ÂÅ’ Error fetching child grades:', error);
      next(error);
    }
  }
);

/**
 * GET /api/parent/child/:studentId/attendance
 * Get attendance for a linked child
 * Ã°Å¸â€â€™ PARENT only (must have link with can_view_academics=true)
 */
app.get('/api/parent/child/:studentId/attendance',
  requireAuth,
  requireRole(['PARENT']),
  async (req, res, next) => {
    try {
      const parentId = req.user.id;
      const { studentId } = req.params;
      const { classId } = req.query;

      // Verify parent has access
      const { data: link, error: linkError } = await supabase
        .from('parent_student_links')
        .select('id, can_view_academics')
        .eq('parent_id', parentId)
        .eq('student_id', studentId)
        .eq('status', 'active')
        .single();

      if (linkError || !link) {
        return res.status(403).json({
          success: false,
          message: 'BÃ¡ÂºÂ¡n khÃƒÂ´ng cÃƒÂ³ quyÃ¡Â»Ân xem thÃƒÂ´ng tin hÃ¡Â»Âc viÃƒÂªn nÃƒÂ y'
        });
      }

      if (!link.can_view_academics) {
        return res.status(403).json({
          success: false,
          message: 'BÃ¡ÂºÂ¡n khÃƒÂ´ng cÃƒÂ³ quyÃ¡Â»Ân xem Ã„â€˜iÃ¡Â»Æ’m danh cÃ¡Â»Â§a hÃ¡Â»Âc viÃƒÂªn nÃƒÂ y'
        });
      }

      // Get enrollments first
      let enrollmentsQuery = supabase
        .from('enrollments')
        .select('id, class:classes(id, name, code)')
        .eq('student_id', studentId)
        .eq('status', 'active');

      if (classId) {
        enrollmentsQuery = enrollmentsQuery.eq('class_id', classId);
      }

      const { data: enrollments, error: enrollError } = await enrollmentsQuery;
      if (enrollError) throw enrollError;

      const enrollmentIds = (enrollments || []).map(e => e.id);

      // Get attendance records
      const { data: attendance, error } = await supabase
        .from('attendance')
        .select(`
          id, session_date, session_number, status, notes,
          enrollment:enrollments(
            id,
            class:classes(id, name, code)
          )
        `)
        .in('enrollment_id', enrollmentIds)
        .order('session_date', { ascending: false });

      if (error) throw error;

      // Calculate stats
      const total = attendance?.length || 0;
      const present = (attendance || []).filter(a => a.status === 'present').length;
      const absent = (attendance || []).filter(a => a.status === 'absent').length;
      const late = (attendance || []).filter(a => a.status === 'late').length;
      const excused = (attendance || []).filter(a => a.status === 'excused').length;
      const attendanceRate = total > 0 ? Math.round((present + late) / total * 100) : 0;

      console.log(`Ã°Å¸â€œâ€¹ Parent viewing child attendance: ${total} records`);

      res.json({
        success: true,
        data: {
          attendance: (attendance || []).map(a => ({
            id: a.id,
            sessionDate: a.session_date,
            sessionNumber: a.session_number,
            status: a.status,
            notes: a.notes,
            className: a.enrollment?.class?.name,
            classCode: a.enrollment?.class?.code
          })),
          stats: {
            total,
            present,
            absent,
            late,
            excused,
            attendanceRate
          },
          classes: (enrollments || []).map(e => ({
            id: e.class?.id,
            name: e.class?.name,
            code: e.class?.code
          }))
        }
      });
    } catch (error) {
      console.error('Ã¢ÂÅ’ Error fetching child attendance:', error);
      next(error);
    }
  }
);

