// GET /api/admin/leave-requests - List leave requests for admin
app.get('/api/admin/leave-requests', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const supabaseClient = req.supabase || supabase;
    const { effectiveCenterId, error: permError } = getEffectiveCenterId(req.user, req.query.center_id);
    if (permError) {
      return res.status(403).json({ success: false, error: permError });
    }

    const { status, page = 1, limit = 20 } = req.query;
    const offset = (parseInt(page) - 1) * parseInt(limit);

    const buildLeaveRequestsSelect = (relationAlias) => `
        id,
        leave_type,
        start_date,
        end_date,
        reason,
        status,
        reviewer_note:reviewer_notes,
        created_at,
        teacher:users!${relationAlias}(id, full_name, email)
      `;

    const relationAliases = ['leave_requests_staff_id_fkey', 'leave_requests_teacher_id_fkey'];
    let data = null;
    let error = null;
    let count = 0;

    for (const relationAlias of relationAliases) {
      let query = supabaseClient
        .from('leave_requests')
        .select(buildLeaveRequestsSelect(relationAlias), { count: 'exact' })
        .order('created_at', { ascending: false })
        .range(offset, offset + parseInt(limit) - 1);

      if (effectiveCenterId) {
        query = query.eq('center_id', effectiveCenterId);
      }
      if (status) {
        query = query.eq('status', status);
      }

      const result = await query;
      data = result.data;
      error = result.error;
      count = result.count;

      if (!error) {
        break;
      }
    }

    if (error) throw error;

    res.json({
      success: true,
      data: data || [],
      pagination: { page: parseInt(page), limit: parseInt(limit), total: count || 0 }
    });
  } catch (error) {
    console.error('Error fetching admin leave requests:', error);
    next(error);
  }
});

// PATCH /api/admin/leave-requests/:id - Approve/reject leave request
app.patch('/api/admin/leave-requests/:id', requireAuth, requireRole(['SUPER_ADMIN', 'CENTER_MANAGER']), async (req, res, next) => {
  try {
    const { id } = req.params;
    const { status, admin_note } = req.body;
    const supabaseClient = req.supabase || supabase;

    if (!status || !['approved', 'rejected'].includes(status)) {
      return res.status(400).json({ success: false, error: 'Status must be approved or rejected' });
    }

    const { data: existing, error: fetchError } = await supabaseClient
      .from('leave_requests')
      .select('id, status')
      .eq('id', id)
      .single();

    if (fetchError || !existing) {
      return res.status(404).json({ success: false, error: 'Leave request not found' });
    }
    if (existing.status !== 'pending') {
      return res.status(400).json({ success: false, error: 'Leave request already processed' });
    }

    const { data, error } = await supabaseClient
      .from('leave_requests')
      .update({
        status,
        reviewer_notes: admin_note || null,
        reviewed_by: req.user.id,
        reviewed_at: new Date().toISOString()
      })
      .eq('id', id)
      .select()
      .single();

    if (error) throw error;

    AuditLogService.log({
      ...getAuditContext(req),
      action: status === 'approved' ? 'LEAVE_APPROVED' : 'LEAVE_REJECTED',
      entityType: 'leave_request',
      entityId: id,
      status: 'SUCCESS'
    });

    try {
      createNotification(supabaseClient, {
        userId: data?.staff_id || data?.teacher_id,
        centerId: data?.center_id,
        type: 'leave_request',
        title: status === 'approved' ? 'ÄÆ¡n nghá»‰ Ä‘Ã£ Ä‘Æ°á»£c duyá»‡t' : 'ÄÆ¡n nghá»‰ Ä‘Ã£ bá»‹ tá»« chá»‘i',
        message: status === 'approved'
          ? 'ÄÆ¡n xin nghá»‰ cá»§a báº¡n Ä‘Ã£ Ä‘Æ°á»£c quáº£n lÃ½ phÃª duyá»‡t.'
          : `ÄÆ¡n xin nghá»‰ cá»§a báº¡n Ä‘Ã£ bá»‹ tá»« chá»‘i${admin_note ? `: ${admin_note}` : '.'}`,
        referenceId: data?.id,
        referenceType: 'leave_request'
      }).catch((notifyError) => {
        console.warn('Notification error (leave decision):', notifyError?.message || notifyError);
      });
    } catch (notificationError) {
      console.warn('Notification enqueue error (leave decision):', notificationError?.message || notificationError);
    }

    res.json({ success: true, data });
  } catch (error) {
    console.error('Error updating leave request:', error);
    next(error);
  }
});

